const ids = ["COR-1253","COR-1254","COR-1255","ENT-1601","COR-1009","COR-1085","COR-1083","COR-1099"];
const [children, ...results] = await Promise.all([
  tools.mcp__linear__list_issues({
    parentId:"COR-1252",
    includeArchived:true,
    limit:250,
    fields:["id","title","description","priority","url","gitBranchName","createdAt","updatedAt","completedAt","startedAt","canceledAt","status","statusType","parentId","assignee"]
  }),
  ...ids.flatMap(id => [
    tools.mcp__linear__get_issue({id,includeRelations:true,includeReleases:true}),
    tools.mcp__linear__list_comments({issueId:id,limit:250,orderBy:"updatedAt"})
  ])
]);
const grouped = {};
for (let i=0;i<ids.length;i++) grouped[ids[i]]={issue:results[i*2],comments:results[i*2+1]};
text(JSON.stringify({children,grouped}));

function parsed(r){const block=r?.content?.find(x=>x.type==="text"); return block?.text ? JSON.parse(block.text) : r;}
const ids=["ENT-1601","COR-1254","COR-1255","COR-1009","COR-1257","COR-1270"];
const out={};
for (const id of ids){
  const [ir,cr]=await Promise.all([
    tools.mcp__linear__get_issue({id,includeRelations:true,includeReleases:true}),
    tools.mcp__linear__list_comments({issueId:id,limit:250,orderBy:"updatedAt"})
  ]);
  const i=parsed(ir), c=parsed(cr);
  out[id]={
    title:i.title,status:i.status,statusType:i.statusType,updatedAt:i.updatedAt,completedAt:i.completedAt,
    attachments:i.attachments,relations:i.relations,
    comments:(c.comments||[]).map(x=>({createdAt:x.createdAt,updatedAt:x.updatedAt,body:x.body}))
  };
}
text(JSON.stringify(out,null,2));

