 // resource_lifecycle_v1 stream of every REMOTE region, subject and payload
 // verbatim.
 //
 // The local cell is deliberately not a target: entire-core already emitted the
 // event into the local stream (that is what this consumer reads), so publishing
 // it back would feed the consumer its own output — an infinite loop, since here
 // the source and target stream are the same (unlike github_meta_v1, whose
 // source is the separate webhooks_github_v1 stream). meta-fanout's only job is
 // to carry the event to the OTHER cells. With no remotes configured
 // (single-region mode) the fan is a no-op and the delivery simply Acks.
 type lifecycleFanout struct {
 	remotes map[string]metajobs.JetStreamPublisher // cluster_id → remote JetStream

 	// localClusterID is this cell's cluster id (FANOUT_LOCAL_CLUSTER_ID). It is
 	// stamped as the lifecycleFannedByHeader value on every fanned copy so the
 	// one-generation guard in dispatch can suppress echoes. Empty only in
 	// single-region mode, where remotes is also empty and the fan never runs.
 	localClusterID string
 }

 // fan publishes (subject, data) into every remote region. Regions are
 // independent: a failure on one (a region momentarily disconnected) must not
 // stop the others, so we attempt all and return a non-nil error if any failed
 // — the caller Naks and the whole event rides JetStream redelivery; the regions
 // that already accepted it re-publish idempotently (same Nats-Msg-Id within the
 // dedup window).
 func (f *lifecycleFanout) fan(ctx context.Context, subject, msgID string, data []byte, srcHeader nats.Header) error {
 	span := trace.SpanFromContext(ctx)

 	var failed []string
 	var firstErr error
 	for _, clusterID := range f.sortedClusters() {
 		if err := f.publishOne(ctx, f.remotes[clusterID], subject, msgID, data, srcHeader); err != nil {
 			failed = append(failed, clusterID)
 			if firstErr == nil {
 				firstErr = err
 			}
 			slog.ErrorContext(ctx, "Lifecycle fan failed for region; continuing with remaining regions",
 				slog.String("subject", subject),
 				slog.String("cluster_id", clusterID),
 				slog.Any("error", err))
 		}
 	}

 	span.SetAttributes(
 		attribute.Int("entire.fanout.regions", len(f.remotes)),
 		attribute.Int("entire.fanout.regions_failed", len(failed)),
 	)
 	if len(failed) > 0 {
 		span.SetAttributes(attribute.StringSlice("entire.fanout.failed_cluster_ids", failed))
 		return fmt.Errorf("lifecycle fan failed for %d of %d regions (clusters: %v): %w",
 			len(failed), len(f.remotes), failed, firstErr)
 	}
 	return nil
 }

 // publishOne re-publishes the event into one remote region's stream. The source
 // headers are carried verbatim (preserving the dedup Nats-Msg-Id) on a private
 // copy per region, then this publish's trace context is injected so the
 // downstream consumer span parents to meta-fanout rather than the original
 // producer.
 func (f *lifecycleFanout) publishOne(ctx context.Context, js metajobs.JetStreamPublisher, subject, msgID string, data []byte, srcHeader nats.Header) error {
 	ctx, span := otel.Tracer(tracerName).Start(ctx, "resource_lifecycle.fan",
 		trace.WithSpanKind(trace.SpanKindProducer),
 		trace.WithAttributes(
 			attribute.String("messaging.system", "nats"),
 			attribute.String("messaging.operation.type", "publish"),
 			attribute.String("messaging.destination.name", subject),
 		),
 	)
 	defer span.End()

 	msg := &nats.Msg{
 		Subject: subject,
 		Data:    data,
 		Header:  cloneHeader(srcHeader),
 	}
 	// Mark this copy as fanned so the destination cell does not re-export it
 	// (see dispatch). cloneHeader gave us a private copy, so this never mutates
 	// the shared source header.
 	msg.Header.Set(lifecycleFannedByHeader, f.localClusterID)
 	if msgID != "" {
 		msg.Header.Set(metajobs.NatsMsgIDHeader, msgID)
 		span.SetAttributes(attribute.String("messaging.message.id", msgID))
 	}
 	natsmsg.Inject(ctx, msg)

 	pubCtx, cancel := context.WithTimeout(ctx, lifecyclePublishAckWait)
 	defer cancel()
 	ack, err := js.PublishMsg(pubCtx, msg)
 	if err != nil {
 		span.RecordError(err)
 		span.SetStatus(otelcodes.Error, "nats publish")
 		return fmt.Errorf("publish lifecycle event: %w", err)
 	}
 	span.SetAttributes(
 		attribute.Int64("messaging.nats.sequence", int64(ack.Sequence)),
 		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
 	)
 	return nil
 }

 func (f *lifecycleFanout) sortedClusters() []string {
 	out := make([]string, 0, len(f.remotes))
 	for cid := range f.remotes {
 		out = append(out, cid)
 	}
 	sort.Strings(out)
 	return out
 }

