624	// TestLifecycleProbe_NeverCreatedGoesLoudAfterTheStartupBudget is the review
625	// finding on trail #102 at dd2cd57.
626	//
627	// Bounding the fast phase fixed the request and log VOLUME but not the
628	// CLASSIFICATION: the quiet branch keyed on !everBound alone, so a durable that is
629	// never created — creation failing while CONSUMER.INFO answers not-found — stayed at
630	// debug forever. No counter, no escalation, and in US/default mode readiness
631	// deliberately excludes this consumer, so nothing else would have said so either.
632	// That is precisely the gap the probe was added to close.
633	//
634	// It drives the real probeDurable loop against a broker with no stream, and never
635	// touches everBound — the previous test set it by hand, which is exactly why it
636	// could not reach this path. The startup budget is shrunk so the wait is
637	// milliseconds instead of the shipped five seconds.
638	func TestLifecycleProbe_NeverCreatedGoesLoudAfterTheStartupBudget(t *testing.T) {
639		// The stream EXISTS and nothing ever creates the durable — creation failing
640		// while CONSUMER.INFO answers not-found, which is the finding's scenario. (With
641		// no stream at all the error would be ErrStreamNotFound, which already reaches
642		// Health as the canonical rollout-ordering line; that is a different path.)
643		nc, _ := natstest.Env(t, lifecycleTestStream())
644		c := &lifecycleConsumer{
645			nc:                   nc,
646			fanout:               &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{}, localClusterID: "us"},
647			durable:              lifecycleDurable,
648			subject:              lifecycleSubjectFilter,
649			probeStartupAttempts: 2,
650		}
651	
652		buf := captureLogs(t, slog.LevelDebug)
653		ctx, cancel := context.WithCancel(t.Context())
654		done := make(chan struct{})
655		go func() {
656			defer close(done)
657			c.probeDurable(ctx, lifecycleConsumerConfig(c.durable, c.subject))
658		}()
659	
660		// Two startup attempts at 250ms, then the grace is spent and the next probe must
661		// report through Health. Wait for the escalation-eligible line rather than a
662		// fixed sleep.
663		const unreachable = "Lifecycle durable unreachable; reporting NotReady"
664		deadline := time.Now().Add(15 * time.Second)
665		var rec map[string]any
666		for {
667			if rec = logRecord(t, buf, unreachable); rec != nil {
668				break
669			}
670			if time.Now().After(deadline) {
671				cancel()
672				<-done
673				t.Fatalf("a durable that was never created stayed quiet past the startup budget; "+
674					"nothing entered natslog.Health. Log was:\n%s", buf.String())
675			}
676			time.Sleep(20 * time.Millisecond)
677		}
678		cancel()
679		<-done
680	
681		// And it must be loud, not merely present: this is a real outage once the grace
682		// is over, and everBound was never set, so was_bound says which of the two loud
683		// cases this is.
684		if rec["level"] != "ERROR" {
685			t.Errorf("a never-created durable past the startup budget must be logged at ERROR; got level %v in %v", rec["level"], rec)
686		}
687		if rec["was_bound"] != false {
688			t.Errorf("the log should record that this durable had never bound; got %v", rec)
689		}
690		if c.Ready() {
691			t.Error("Ready() must be false while the durable does not exist")
692		}
693	}
694	
695	// safeBuf is a bytes.Buffer that may be written by a probe goroutine while the test
696	// reads it. slog's handler writes from whichever goroutine logs, and a bare
697	// bytes.Buffer is not safe for that — CI caught it as a data race where a local
698	// -race -count=2 had not, because the interleaving needs the write and the poll to
699	// land together.
700	type safeBuf struct {
701		mu  sync.Mutex
702		buf bytes.Buffer
703	}
704	
705	func (b *safeBuf) Write(p []byte) (int, error) {
706		b.mu.Lock()
707		defer b.mu.Unlock()
708		return b.buf.Write(p)
709	}
710	
711	func (b *safeBuf) String() string {
712		b.mu.Lock()
713		defer b.mu.Unlock()
714		return b.buf.String()
715	}
