717	// TestLifecycleProbe_ShutdownCancellationIsNotAFault covers the false-ERROR finding
718	// on trail #102 at 3765557.
719	//
720	// Run cancels the probe's context on the way out, so a CONSUMER.INFO in flight at
721	// that moment returns context.Canceled. That value is not in the transient set, so it
722	// reached Health as a FAULT and logged
723	//
724	//	{"level":"ERROR","msg":"Lifecycle durable unreachable; reporting NotReady","error":"context canceled"}
725	//
726	// on every rollout — self-inflicted shutdown noise, which is the precise thing
727	// natslog was introduced to remove, reintroduced by the probe added to report real
728	// outages.
729	//
730	// Driven with an already-cancelled context and the startup grace OVER, so before the
731	// guard this is exactly the loud path.
732	func TestLifecycleProbe_ShutdownCancellationIsNotAFault(t *testing.T) {
733		nc, js := natstest.Env(t, lifecycleTestStream())
734		c := &lifecycleConsumer{
735			nc:      nc,
736			fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{}, localClusterID: "us"},
737			durable: lifecycleDurable,
738			subject: lifecycleSubjectFilter,
739		}
740		cfg := lifecycleConsumerConfig(c.durable, c.subject)
741	
742		ctx, cancel := context.WithCancel(t.Context())
743		cancel() // the shutdown condition: parent already done
744	
745		buf := captureLogs(t, slog.LevelDebug)
746		if c.durableReachable(ctx, js, cfg, false /* grace over, so any complaint would be loud */) {
747			t.Fatal("a cancelled probe must not report the durable as reachable")
748		}
749		if rec := logRecord(t, buf, "Lifecycle durable unreachable; reporting NotReady"); rec != nil {
750			t.Errorf("our own shutdown was reported as a fault: %v", rec)
751		}
752	
753		// The guard must stay narrow: a real timeout, with the parent alive, still has to
754		// reach Health. Point the probe at a durable that does not exist on a live
755		// context and require the complaint.
756		buf = captureLogs(t, slog.LevelDebug)
757		if c.durableReachable(t.Context(), js, cfg, false) {
758			t.Fatal("a missing durable must not report as reachable")
759		}
760		if rec := logRecord(t, buf, "Lifecycle durable unreachable; reporting NotReady"); rec == nil {
761			t.Errorf("with the parent context alive, a real failure must still reach Health; log was:\n%s", buf.String())
762		}
763	}
764	
765	// captureLogs installs a JSON default logger at the given level and returns the
766	// buffer it writes to.
767	//
768	// It captures the PROCESS-WIDE logger, so a parallel test's output lands here too.
769	// That is why the assertions below look for a specific message and read the level
770	// off THAT record (see logRecord) rather than searching for a bare `"level":"ERROR"`
771	// anywhere in the buffer: another test's unrelated error would satisfy that, and the
772	// test would pass for the wrong reason.
773	func captureLogs(t *testing.T, level slog.Level) *safeBuf {
774		t.Helper()
775		buf := &safeBuf{}
776		prev := slog.Default()
777		slog.SetDefault(slog.New(slog.NewJSONHandler(buf, &slog.HandlerOptions{Level: level})))
778		t.Cleanup(func() { slog.SetDefault(prev) })
779		return buf
780	}
781	
782	// logRecord returns the first captured record whose msg is exactly want, or nil when
783	// none is. Matching on the message rather than scanning the raw text is what keeps
784	// these assertions honest under a shared default logger.
785	func logRecord(t *testing.T, buf *safeBuf, want string) map[string]any {
786		t.Helper()
787		for line := range strings.SplitSeq(strings.TrimSpace(buf.String()), "\n") {
788			if line == "" {
789				continue
790			}
791			var rec map[string]any
792			if err := json.Unmarshal([]byte(line), &rec); err != nil {
793				continue // a non-JSON line from something that logged before capture
794			}
795			if rec["msg"] == want {
796				return rec
797			}
798		}
799		return nil
800	}

