681		// And it must be loud, not merely present: this is a real outage once the grace
682		// is over, and everBound was never set, so was_bound says which of the two loud
683		// cases this is.
684		if rec["level"] != "ERROR" {
685			t.Errorf("a never-created durable past the startup budget must be logged at ERROR; got level %v in %v", rec["level"], rec)
686		}
687		if rec["was_bound"] != false {
688			t.Errorf("the log should record that this durable had never bound; got %v", rec)
689		}
690		if c.Ready() {
691			t.Error("Ready() must be false while the durable does not exist")
692		}
693	}
