530	// TestLifecycleProbe_CadenceBoundsTheStartupBurst covers the log-and-request-volume
531	// finding on trail #102, and the follow-up finding that the first fix did not
532	// actually hold.
533	//
534	// Two properties, and the second is why this drives a state machine rather than a
535	// function: the fast phase must END (bounded by attempts, so a pod starting during an
536	// outage does not poll four times a second forever), and it must NEVER RESUME (so a
537	// post-bind loss does not re-enter that cadence when the server is least able to
538	// answer).
539	//
540	// The version this replaces computed the interval from the outcome plus a raw
541	// attempts-remaining counter. Every single-call assertion passed, and the property
542	// still broke: a success left the counter untouched, so a durable binding on its
543	// first probe kept 19 unspent attempts, and a loss inside the next ~95s went back to
544	// 250ms. A sequence property needs a sequence test.
545	func TestLifecycleProbe_CadenceBoundsTheStartupBurst(t *testing.T) {
546		t.Parallel()
547	
548		t.Run("never binds: fast until the budget is spent, then steady forever", func(t *testing.T) {
549			cad := newProbeCadence(3)
550			if !cad.startupPending() {
551				t.Error("a fresh cadence should still be in its startup phase")
552			}
553			if got := cad.observe(false); got != lifecycleReadyProbeStartupInterval {
554				t.Errorf("attempt 1 interval = %v, want the fast %v", got, lifecycleReadyProbeStartupInterval)
555			}
556			if got := cad.observe(false); got != lifecycleReadyProbeStartupInterval {
557				t.Errorf("attempt 2 interval = %v, want the fast %v", got, lifecycleReadyProbeStartupInterval)
558			}
559			// Budget spent: this is the finding about polling forever during an outage.
560			if got := cad.observe(false); got != lifecycleReadyProbeInterval {
561				t.Errorf("attempt 3 spent the budget; interval = %v, want the steady %v — "+
562					"an outage at boot would otherwise be polled at the fast cadence forever",
563					got, lifecycleReadyProbeInterval)
564			}
565			if cad.startupPending() {
566				t.Error("startupPending should be false once the budget is spent")
567			}
568			for i := range 5 {
569				if got := cad.observe(false); got != lifecycleReadyProbeInterval {
570					t.Errorf("continued failure %d: interval = %v, want the steady %v", i, got, lifecycleReadyProbeInterval)
571				}
572			}
573		})
574	
575		t.Run("binds immediately, then loses the durable: never returns to fast", func(t *testing.T) {
576			// The follow-up finding: binding on the FIRST probe leaves almost the whole
577			// budget unspent, so a later loss must not be able to spend it.
578			cad := newProbeCadence(lifecycleReadyProbeStartupAttempts)
579			if got := cad.observe(true); got != lifecycleReadyProbeInterval {
580				t.Fatalf("a successful probe should settle to the steady %v, got %v", lifecycleReadyProbeInterval, got)
581			}
582			if cad.startupPending() {
583				t.Error("a success must end the startup phase, not merely pause it")
584			}
585			for i := range 5 {
586				if got := cad.observe(false); got != lifecycleReadyProbeInterval {
587					t.Fatalf("loss %d after binding: interval = %v, want the steady %v — "+
588						"re-entering the fast cadence hammers the server exactly when it is least able to answer",
589						i, got, lifecycleReadyProbeInterval)
590				}
591			}
592		})
593	
594		t.Run("binds mid-startup, then loses the durable: never returns to fast", func(t *testing.T) {
595			cad := newProbeCadence(4)
596			_ = cad.observe(false) // one attempt spent, budget still open
597			if !cad.startupPending() {
598				t.Fatal("the startup phase should still be open after one failed attempt")
599			}
600			if got := cad.observe(true); got != lifecycleReadyProbeInterval {
601				t.Fatalf("a successful probe should settle to the steady %v, got %v", lifecycleReadyProbeInterval, got)
602			}
603			if got := cad.observe(false); got != lifecycleReadyProbeInterval {
604				t.Errorf("loss after a mid-startup bind: interval = %v, want the steady %v", got, lifecycleReadyProbeInterval)
605			}
606		})
607	
608		// The constants themselves have to make the phase meaningful: a fast cadence at
609		// or above the steady one is not a burst, a zero bound removes the phase the
610		// create race needs, and a burst measured in minutes would be no better than an
611		// unbounded one for log volume.
612		if lifecycleReadyProbeStartupInterval >= lifecycleReadyProbeInterval {
613			t.Errorf("startup interval %v is not faster than the steady %v",
614				lifecycleReadyProbeStartupInterval, lifecycleReadyProbeInterval)
615		}
616		if lifecycleReadyProbeStartupAttempts <= 0 {
617			t.Errorf("startup attempts = %d, want a positive bound", lifecycleReadyProbeStartupAttempts)
618		}
619		if burst := time.Duration(lifecycleReadyProbeStartupAttempts) * lifecycleReadyProbeStartupInterval; burst > 30*time.Second {
620			t.Errorf("the fast phase can last %v, which is long enough to be a log-volume problem of its own", burst)
