@@ -282,210 +282,210 @@ func run() (retErr error) {
 		)

 		// Backfill consumer: a SEPARATE durable on the dedicated, US-only
 		// github_meta_backfill work-queue stream, with its own per-replica
 		// GitHub-API throttle (META_FANOUT_BACKFILL_GH_RPS; the effective regional
 		// rate is that value times the replica count), so a one-shot region-wide
 		// backfill stays well under GitHub's rate limit and doesn't starve the live
 		// webhooks_github_v1 fan-out above. Unlike the
 		// live producer (metadata off the webhook body), a backfill has no webhook,
 		// so the worker fetches each repo's current metadata from GitHub using an
 		// installation token minted via entire-core's STS — the same auth
 		// mirror-worker uses (coreapp.Minter over the shared internal mTLS cert; the
 		// reloader picks up cert-manager rotations). The stream is provisioned in
 		// fleet; if it isn't present yet the consumer logs + retries (never crashes).
 		coreInternalURL := os.Getenv("ENTIRE_CORE_INTERNAL_URL")
 		reloader, err := authmtls.NewReloader(
 			os.Getenv("ENTIRE_INTERNAL_TLS_CERT_FILE"),
 			os.Getenv("ENTIRE_INTERNAL_TLS_KEY_FILE"),
 			os.Getenv("ENTIRE_INTERNAL_TLS_CA_FILE"),
 		)
 		if err != nil {
 			return fmt.Errorf("load internal mTLS cert for backfill minter: %w", err)
 		}
 		go reloader.Watch(ctx, authmtls.DefaultReloadInterval)

 		// One STS minter shared by both backfill consumers (the meta and PR
 		// backfills mint installation tokens the same way over the same internal
 		// mTLS client; the reloader picks up cert rotations under it).
 		minter := coreapp.NewMinter(coreapp.Config{IssuerURL: coreInternalURL, HTTPClient: authmtls.NewClient(reloader)})

 		backfillDurableName := os.Getenv("META_FANOUT_BACKFILL_DURABLE")
 		if backfillDurableName == "" {
 			backfillDurableName = backfillDurable
 		}
 		backfillRPS := parseBackfillRPS(os.Getenv("META_FANOUT_BACKFILL_GH_RPS"))
 		backfillRes := newBackfillResolver(
 			resolver,
 			minter,
 			newGitHubRepoClient(os.Getenv("ENTIRE_GITHUB_API_BASE_URL")),
 			newRPSThrottle(backfillRPS),
 		)
