  new_string: string;
  // Exact text to replace. Must match the current content exactly once
  old_string: string;
  op: "replace";
  // Replace every occurrence instead of requiring a unique match
  replace_all?: boolean;
} | {
  // Exact text to insert before. Must match the current content exactly once
  anchor: string;
  op: "insert_before";
