	// every cell. Provisioned declaratively in fleet (apps/nats-streams) —
	// meta-fanout neither creates nor reconciles it, it only consumes the local
	// copy and re-publishes into each remote cell's copy.
	lifecycleStream = "resource_lifecycle_v1"

	// lifecycleSubjectFilter binds the consumer to the whole stream. meta-fanout
	// is a dumb cross-region pipe for resource_lifecycle_v1: it fans every
	// subtype (github_handle.*, verified_email.*, and the org/project/repo
	// binding events that share the bus) and leaves subtype filtering to the
	// per-cell consumers downstream.
	lifecycleSubjectFilter = lifecycleStream + ".>"

	// lifecycleDurable is meta-fanout's durable on the LOCAL
	// resource_lifecycle_v1 stream — distinct from the github_meta webhook and
	// backfill durables so the three drain independently. Overridable via env for
	// non-prod / migration.
	lifecycleDurable = "meta-fanout-lifecycle"

	// lifecyclePublishAckWait bounds the synchronous pub-ack on each remote
	// region's PublishMsg (the shared natspub.AckWait, so the lifecycle fan
	// can't drift from the job publishers). A publish routed to a reconnecting
	// region becomes a bounded error → consumer Nak → JetStream redelivery,
	// instead of parking in the client's reconnect buffer and stalling the
	// serial consume loop until the region returns.
	lifecyclePublishAckWait = natspub.AckWait

	// lifecycleFannedByHeader marks a resource_lifecycle_v1 event as an
	// already-fanned cross-region copy. publishOne stamps it (value = the
	// fanning cell's cluster id) on every copy it emits; dispatch skips
	// re-fanning any event that already carries it. That makes the fan exactly
	// one generation deep: an event fanned US→EU is not re-fanned by EU back to
	// US or on to AP, so a cross-region echo loop is structurally impossible at
	// any lag — independent of the destination dedup window (COR-902). The value
	// is for debuggability (which cell exported it); the guard keys on presence.
	// Carried verbatim across hops like any user header, so once stamped it stays
	// stamped.
	lifecycleFannedByHeader = "Entire-Lifecycle-Fanned-By"

	// lifecycleMaxAckPending is stated rather than left to default, and the value
	// is a deliberate change from what the live durables carry (COR-1254 loop 1).
	//
	// All seven cells had 65536 — not the server's 1000 default and not a tuned
	// number: nats.go's legacy PullSubscribe copies its own client-side
	// subscription-channel capacity into the server config (js.go, cfg.MaxAckPending
	// = cap(ch)), so nobody ever chose it. jsconsumer sends the field on every
	// start, so leaving it zero would have rewritten all seven to 1000 silently;
	// this makes that the recorded decision instead. The bound is generous either
	// way — this consumer prefetches one message (MaxMessages below), so
	// in-flight work is one delivery per replica.
	lifecycleMaxAckPending = 1000

	// lifecycleReadyProbeInterval and lifecycleReadyProbeTimeout pace the /readyz
	// liveness probe (see lifecycleConsumer.durableBound). 5s is well inside a
	// kubelet readiness period, so a genuine outage is reported within one probe
	// while costing one CONSUMER.INFO per pod per 5s. The timeout is shorter than
	// the interval so a hung probe cannot leave the answer stale indefinitely.
	lifecycleReadyProbeInterval = 5 * time.Second
	lifecycleReadyProbeTimeout  = 3 * time.Second
	// lifecycleReadyProbeStartupInterval is the cadence until the FIRST successful
	// probe. The first attempt races jsconsumer.Run creating the durable, so
	// without it a healthy pod reports NotReady for a whole steady interval after
	// it is already consuming. It applies only before the first success, so a
	// sustained outage is polled at the steady rate, not this one.
	lifecycleReadyProbeStartupInterval = 250 * time.Millisecond
	// lifecycleReadyProbeStartupAttempts bounds that fast phase so it cannot
	// outlive the race it exists for. 20 attempts at 250ms is ~5s — orders of
	// magnitude more than creating a durable takes — after which the probe settles
	// to the steady cadence whether or not it ever succeeded. Without this bound a
	// pod that starts during an outage polls four times a second forever.
	lifecycleReadyProbeStartupAttempts = 20
)

// lifecycleFanout re-publishes one resource_lifecycle_v1 event into the local
// resource_lifecycle_v1 stream of every REMOTE region, subject and payload
// verbatim.
//
// The local cell is deliberately not a target: entire-core already emitted the
// event into the local stream (that is what this consumer reads), so publishing
// it back would feed the consumer its own output — an infinite loop, since here
// the source and target stream are the same (unlike github_meta_v1, whose
// source is the separate webhooks_github_v1 stream). meta-fanout's only job is
// to carry the event to the OTHER cells. With no remotes configured
// (single-region mode) the fan is a no-op and the delivery simply Acks.
type lifecycleFanout struct {
	remotes map[string]metajobs.JetStreamPublisher // cluster_id → remote JetStream

	// localClusterID is this cell's cluster id (FANOUT_LOCAL_CLUSTER_ID). It is
	// stamped as the lifecycleFannedByHeader value on every fanned copy so the
	// one-generation guard in dispatch can suppress echoes. Empty only in
	// single-region mode, where remotes is also empty and the fan never runs.
	localClusterID string
}

// fan publishes (subject, data) into every remote region. Regions are
// independent: a failure on one (a region momentarily disconnected) must not
// stop the others, so we attempt all and return a non-nil error if any failed
// — the caller Naks and the whole event rides JetStream redelivery; the regions
// that already accepted it re-publish idempotently (same Nats-Msg-Id within the
// dedup window).
func (f *lifecycleFanout) fan(ctx context.Context, subject, msgID string, data []byte, srcHeader nats.Header) error {
	span := trace.SpanFromContext(ctx)

	var failed []string
	var firstErr error
	for _, clusterID := range f.sortedClusters() {
		if err := f.publishOne(ctx, f.remotes[clusterID], subject, msgID, data, srcHeader); err != nil {
			failed = append(failed, clusterID)
			if firstErr == nil {
				firstErr = err
			}
			slog.ErrorContext(ctx, "Lifecycle fan failed for region; continuing with remaining regions",
				slog.String("subject", subject),
				slog.String("cluster_id", clusterID),
				slog.Any("error", err))
		}
	}

	span.SetAttributes(
		attribute.Int("entire.fanout.regions", len(f.remotes)),
		attribute.Int("entire.fanout.regions_failed", len(failed)),
	)
	if len(failed) > 0 {
		span.SetAttributes(attribute.StringSlice("entire.fanout.failed_cluster_ids", failed))
		return fmt.Errorf("lifecycle fan failed for %d of %d regions (clusters: %v): %w",
			len(failed), len(f.remotes), failed, firstErr)
	}
	return nil
}

// publishOne re-publishes the event into one remote region's stream. The source
// headers are carried verbatim (preserving the dedup Nats-Msg-Id) on a private
// copy per region, then this publish's trace context is injected so the
// downstream consumer span parents to meta-fanout rather than the original
// producer.
func (f *lifecycleFanout) publishOne(ctx context.Context, js metajobs.JetStreamPublisher, subject, msgID string, data []byte, srcHeader nats.Header) error {
	ctx, span := otel.Tracer(tracerName).Start(ctx, "resource_lifecycle.fan",
		trace.WithSpanKind(trace.SpanKindProducer),
		trace.WithAttributes(
			attribute.String("messaging.system", "nats"),
			attribute.String("messaging.operation.type", "publish"),
			attribute.String("messaging.destination.name", subject),
		),
	)
	defer span.End()

	msg := &nats.Msg{
		Subject: subject,
		Data:    data,
		Header:  cloneHeader(srcHeader),
	}
	// Mark this copy as fanned so the destination cell does not re-export it
	// (see dispatch). cloneHeader gave us a private copy, so this never mutates
	// the shared source header.
	msg.Header.Set(lifecycleFannedByHeader, f.localClusterID)
	if msgID != "" {
		msg.Header.Set(metajobs.NatsMsgIDHeader, msgID)
		span.SetAttributes(attribute.String("messaging.message.id", msgID))
	}
	natsmsg.Inject(ctx, msg)

	pubCtx, cancel := context.WithTimeout(ctx, lifecyclePublishAckWait)
	defer cancel()
	ack, err := js.PublishMsg(pubCtx, msg)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "nats publish")
		return fmt.Errorf("publish lifecycle event: %w", err)
	}
	span.SetAttributes(
		attribute.Int64("messaging.nats.sequence", int64(ack.Sequence)),
		attribute.Bool("messaging.nats.duplicate", ack.Duplicate),
	)
	return nil
}

func (f *lifecycleFanout) sortedClusters() []string {
	out := make([]string, 0, len(f.remotes))
	for cid := range f.remotes {
		out = append(out, cid)
	}
	sort.Strings(out)
	return out
}

// lifecycleConsumer drains the LOCAL resource_lifecycle_v1 stream and fans each
// event cross-region. Its own durable keeps it isolated from the github_meta
// webhook and backfill consumers on their own streams.
//
// # Retry ownership (COR-1254, loop 1)
//
// The redelivery ladder is the SERVER's: the durable carries [lifecycleBackOff],
// and the app's disposition for a failed fan is to DO NOTHING — the delivery is
// left for the ack timeout to bring back on that ladder. The two alternatives are
// both wrong. A client-side NakWithDelay alongside a server ladder is the
// ENT-1535 defect itself (the server stretches each NAK delay by the BackOff
// increments, so redeliveries follow neither and the configured one becomes dead
// config). A plain Nak redelivers immediately, skipping the ladder entirely.
//
// There is still no Term path and no DLQ. The event is republished verbatim, so
// nothing about it can be permanently unprocessable; and resource_lifecycle_v1 is

