# resource_lifecycle_v1 — control-plane resource-lifecycle notification bus,
# one Limits stream per region.
#
# Captures the org/project/repo/grant/member/service-account/mirror lifecycle
# events that entiredb's resourceevents.Emitter already publishes best-effort on
# resource_lifecycle_v1.<resource_type>.<op> (e.g. resource_lifecycle_v1.repo.deleted).
# Two new types on this same subject — github_handle.created and
# verified_email.created — drive /me author-attribution reprocessing in
# entire-api; declaring the stream here makes those (and the pre-existing
# org/project/repo/grant events the git-data reaper + entire-search want) durable.
# Until this CR exists the publishes are emit-to-void — delivered only to live
# subscribers and otherwise dropped (see entiredb core/resourceevents).
#
# Lives in EVERY NATS cluster (base/), the same all-region footprint as
# github_meta_v1 / user_activity_v1 — available per-jurisdiction in all three
# regions (US, EU, AU) so each region's entire-api can bind a consumer locally.
#
# Cross-region fan-out (producer side, NOT this CR — entire-core, separate PR):
# the event originates centrally but every region's consumer needs it, so the
# producer publishes one copy into EACH region's local NATS island — exactly the
# github_meta_v1 meta-fanout shape. Fleet's half is declaring the durable target
# stream in every cell; the fan-out publish lives in the entire-core PR.
#
# Producer: entiredb resourceevents.Emitter (best-effort core NATS, no PubAck —
# a publish failure is logged and swallowed, never failing the API request).
# Consumers (separate PRs): independent durables — entire-api /me
# reprocessing, the entiredb git-data reaper, entire-search — each replays the
# full subject independently and re-queries the system of record (Postgres /
# entiredb) by (resource_type, resource_id).
#
# Retention=limits + discard=old (the repo_refs_v1 notification-bus shape, NOT
# workqueue like github_meta_v1 / user_activity_v1): the events are notifications,
# not the system of record, and MULTIPLE independent durables each need their own
# copy of every event — a WorkQueue stream removes each message on the first ack
# and rejects overlapping consumers, so it cannot fan a single event out to all
# three consumer services. discard=old lets a publish spike evict the oldest
# notification rather than reject the publish (the emitter is best-effort and
# must never block an API mutation; nothing authoritative is lost — consumers
# re-query the origin).
#
# Declaratively owned here (nack) instead of created imperatively by a binary at
# startup — see apps/nats-streams/README.md. maxBytes is uniform across clusters
# (low-volume control-plane mutations, tiny JSON projections); the staging
# overlays trim maxAge to 6h (prod keeps the 96h default below).
apiVersion: jetstream.nats.io/v1beta2
kind: Stream
metadata:
  name: resource-lifecycle-v1
spec:
  name: resource_lifecycle_v1
  # Flux runs prune: true — without this, deleting or renaming this CR would
  # make nack DELETE the live stream (and everything queued in it). Guard it.
  preventDelete: true
  subjects:
    - "resource_lifecycle_v1.>"
  retention: limits
  discard: old
  storage: file
  replicas: 3
  maxBytes: 536870912 # 512 MiB — small JSON projections, low-volume control-plane events
  maxAge: 96h0m0s # 4d backstop for an undrained event; staging overlays trim to 6h
  duplicateWindow: 2m0s # the emitter does not set Nats-Msg-Id today (best-effort,
  # at-most-once), so this is a no-op safety default rather than an active dedup
  # contract — kept for parity with the other CRs and to dedup if the producer
  # ever starts stamping message IDs.
package main

import (
	"testing"
	"time"

	"github.com/entirehq/mirror-pipeline/internal/timingcontract"
	"github.com/entireio/go-nuts/jsconsumer"
)

// stagingLifecycleMaxAge is the tightest retention any cell gives
// resource_lifecycle_v1: the base stream CR sets 96h, and the staging overlays
// trim it to 6h. The ladder is checked against the tight one, since a ladder that
// outlives retention never reaches its own end — the message is discarded first.
const stagingLifecycleMaxAge = 6 * time.Hour

// TestLifecycleTimingContract validates the shipped schedule and renders the
// before/after table this migration's trail carries.
//
// "Before" is the MEASURED durable, not the old constants read back: snapshots of
// all seven cells (4 prod + 3 staging) on 2026-08-14 showed no server-side
// backoff on this durable, so the effective ladder really was the client's flat
// NakWithDelay — unlike webhook-forwarder and fanout, which turned out to carry an
// undeclared 41h ladder (COR-1270). That is why loop 1 can claim an
// envelope-preserving migration and loop 2 cannot.
func TestLifecycleTimingContract(t *testing.T) {
	t.Parallel()

	before := timingcontract.Contract{
		Name: "before (client Nak, measured)",
		Schedule: jsconsumer.Schedule{
			NakDelay:     consumerFailureDelay,
			MaxDeliver:   consumerMaxDeliver,
			AckWait:      consumerAckWait,
			StreamMaxAge: stagingLifecycleMaxAge,
		},
	}
	after := timingcontract.Contract{
		Name:     "after (server ladder)",
		Schedule: lifecycleSchedule(),
	}
	after.Schedule.StreamMaxAge = stagingLifecycleMaxAge

	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.Validate(); err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
	}

	// The property loop 1 promises: the envelope does not move. Only ownership of
	// the schedule does.
	want := timingcontract.Envelope{
		DeadLetterDelivery: consumerMaxDeliver,
		TimeToDeadLetter:   time.Duration(consumerMaxDeliver-1) * consumerFailureDelay,
		LongestRung:        consumerFailureDelay,
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.CheckEnvelope(want); err != nil {
			t.Error(err)
		}
	}

	t.Logf("lifecycle timing contract:\n%s", timingcontract.Markdown(before, after))
}

// TestLifecycleLadderRungsMatchMaxDeliver pins the rung count against the delivery
// cap — the first of the "three MaxDeliver numbers must agree" (ENT-1601). The
// third, a Retry's own MaxDeliver, does not exist for this consumer: it has no
// Retry, because it has no DLQ to capture into.
//
// The server rejects len(BackOff) > MaxDeliver outright, so getting this wrong is
// a startup failure rather than a silent one; the test exists so the derivation in
// lifecycleBackOff cannot be replaced by a hand-written list that drifts.
func TestLifecycleLadderRungsMatchMaxDeliver(t *testing.T) {
	t.Parallel()
	rungs := lifecycleBackOff()
	if len(rungs) != consumerMaxDeliver-1 {
		t.Errorf("ladder has %d rungs for MaxDeliver %d; want %d — one per redelivery",
			len(rungs), consumerMaxDeliver, consumerMaxDeliver-1)
	}
	for i, d := range rungs {
		if d != consumerFailureDelay {
			t.Errorf("rung %d = %v, want the flat %v", i, d, consumerFailureDelay)
		}
	}
	// AckWait must equal the first rung or the server stores the rung in its place
	// and the declared AckWait never runs (measured in
	// natstest.REDACTED).
	if consumerAckWait != rungs[0] {
		t.Errorf("AckWait %v disagrees with BackOff[0] %v", consumerAckWait, rungs[0])
	}
}

