// nothing about it can be permanently unprocessable; and resource_lifecycle_v1 is
// limits-retention, holding every event for its full max age whatever this
// consumer does — so the replay path is the source stream, not a capture stream.
// Adding one would need a DLQ stream and a meta-fanout publish grant that do not
// exist; deliberately out of scope here.
type lifecycleConsumer struct {
	nc      *nats.Conn
	fanout  *lifecycleFanout
	metrics *metaFanoutMetrics
	durable string
	subject string

	// enqueuer + resolver drive the additive mirror.created → github_meta seed
	// (COR-717). Both nil leaves the consumer a pure cross-region fan (its
	// original behavior), so fan-only tests need not wire them.
	enqueuer backfillEnqueuer
	resolver mirrorResolver

	// health carries the failure-run supervision the hand-rolled subscribe loop
	// used to hold, now driven by the readiness probe rather than by Fetch errors:
	// warn while a failure is being absorbed, error once five minutes have passed
	// with no recovery, and the restart-proof recoverable_failures counter either
	// way. jsconsumer.Run has no equivalent — it warns per attempt, indefinitely —
	// so without this a sustained outage was indistinguishable from deploy churn.
	// Zero value is healthy and ready to use.
	health natslog.Health

	// configRejected records that [jsconsumer.Run] returned, which it does only
	// for a configuration the broker will never accept — never for a transient
	// failure it can retry. /readyz consults it, so a durable this deployment
	// cannot create reports NotReady rather than looking healthy while consuming
	// nothing. That is this migration's likeliest failure mode: an
	// immutable-field disagreement against the live consumer.
	//
	// On its own this covers only a PERMANENT rejection, which is not enough for
	// a readiness gate — hence durableBound below.
	configRejected atomic.Bool

	// durableBound is the liveness half of /readyz: whether this pod's durable can
	// actually be reached on the server right now, refreshed by a slow probe while
	// Run supervises the consume loop.
	//
	// It exists because jsconsumer.Run exposes no start-success signal. Run retries
	// every failure it can and logs a warning per attempt, so configRejected alone
	// would leave /readyz green through exactly the outages the gate is for: a
	// stream not provisioned yet, a JetStream API that is unreachable while the TCP
	// connection is up (no responders, meta-leader election, a CONSUMER.CREATE
	// permission rejection that manifests as a timeout). The pre-existing
	// natsregions health check does NOT cover those — it only asks IsConnected —
	// and in lifecycle-only mode this consumer is the pod's SOLE readiness gate, so
	// a green /readyz through such a window would hide a real outage. That is the
	// regression the pre-migration `subscribed` bool did not have.
	//
	// What it proves: the stream and durable exist and the JetStream API answered.
	// What it does not: that this process is the one consuming (another replica
	// shares the durable), or that a delivery arrived. It is a strictly better
	// proxy than configRejected for every case above, and it starts false so a pod
	// is NotReady until the first probe succeeds — matching the old gate's boot
	// behaviour.
	//
	// A go-nuts follow-up should make this unnecessary by exposing readiness from
	// Run, beside the Runner.Drain and FloorMonitor-attach gaps entire-search #131
	// logged. Loops 2+ each have a /readyz gate of their own and will want this
	// extracted; left local until a second caller exists rather than inventing a
	// shared shape from one example.
	durableBound atomic.Bool

	// everBound records that the durable has been reachable at least once. It
	// separates "not created yet" from "disappeared after binding" — the same error
	// value, two very different events — and it is one-way on purpose: re-entering
	// the startup posture after a real disappearance would both silence it and
	// hammer the server at the fast cadence when it is least able to answer.
	everBound atomic.Bool

	// probeStartupAttempts overrides lifecycleReadyProbeStartupAttempts. Zero uses
	// the constant; a test shrinks it so the never-created-after-the-budget path
	// can be driven in milliseconds rather than the five seconds the shipped value
	// takes. The only knob of its kind here, and it exists because that path is the
	// one a manual everBound in a test cannot reach.
	probeStartupAttempts int
}

// startupProbeAttempts is the startup budget in force: the override when set,
// otherwise the shipped constant.
func (c *lifecycleConsumer) startupProbeAttempts() int {
	if c.probeStartupAttempts > 0 {
		return c.probeStartupAttempts
	}
	return lifecycleReadyProbeStartupAttempts
}

// Ready reports whether this consumer is configured acceptably AND its durable is
// currently reachable. See the field docs for what each half does and does not
// prove.
func (c *lifecycleConsumer) Ready() bool {
	return !c.configRejected.Load() && c.durableBound.Load()
}

// lifecycleBackOff is the server-owned ladder: consumerFailureDelay served before
// every redelivery consumerMaxDeliver allows.
//
// Derived from those two constants rather than written out, so the numbers that
// must agree cannot drift — the durable's MaxDeliver, len(BackOff) under the
// server's tail-repeat, and (for a consumer that has one) its Retry's MaxDeliver.
// The ladder is flat because the fan's failure mode is a momentarily unreachable
// region, which does not get cheaper to wait out; MaxDeliver bounds the envelope.
func lifecycleBackOff() []time.Duration {
	rungs := make([]time.Duration, consumerMaxDeliver-1)
	for i := range rungs {
		rungs[i] = consumerFailureDelay
	}
	return rungs
}

// lifecycleSchedule is this durable's timing contract as data. Stated once here:
// the redeliver-in log line below reads its rungs, and the timing-contract test
// validates it through jsconsumer.Schedule rather than restating the arithmetic.
func lifecycleSchedule() jsconsumer.Schedule {
	return jsconsumer.Schedule{
		ServerBackOff: lifecycleBackOff(),
		MaxDeliver:    consumerMaxDeliver,
		AckWait:       consumerAckWait,
	}
}

// lifecycleConsumerConfig is the durable's full configuration. Every field the
// pre-migration PullSubscribe left implicit is stated, because
// CreateOrUpdateConsumer sends them all: a field omitted here is not "unchanged
// on the live durable", it is reset to a default.
func lifecycleConsumerConfig(durable, subject string) jsconsumer.Config {
	return jsconsumer.Config{
		Stream:        lifecycleStream,
		Durable:       durable,
		FilterSubject: subject,
		AckWait:       consumerAckWait,
		MaxDeliver:    consumerMaxDeliver,
		BackOff:       lifecycleBackOff(),
		MaxAckPending: lifecycleMaxAckPending,
		// InactiveThreshold stays unset, deliberately. The 2026-06-01 safety
		// valve applies to interest-retention streams, where an abandoned durable
		// pins every subsequent delivery for ALL consumers until the stream's
		// maxAge; resource_lifecycle_v1 is limits-retention, so an idle durable
		// pins nothing and reaping it would only cost a cursor. The live durables
		// carry no threshold in any of the seven cells and none is added here.
		InactiveThreshold: 0,
		// One message client-side, preserving the pre-migration Fetch(1) pacing:
		// AckWait runs from server delivery into the buffer, not from callback
		// dispatch, so anything queued behind a slow fan would age unprocessed.
		MaxMessages: 1,
		SpanName:    "meta_fanout.lifecycle_fan", // preserve the existing span name verbatim
		Name:        "meta-fanout-lifecycle",
		Tracer:      otel.Tracer(tracerName),
	}
}

// Run consumes until ctx is cancelled, then joins the in-flight handler before
// returning — so the caller may tear down what the handler uses (the remote
// publish handles, the connection) the moment it returns.
func (c *lifecycleConsumer) Run(ctx context.Context) {
	cfg := lifecycleConsumerConfig(c.durable, c.subject)

	// The readiness probe lives as long as the consume loop: derive a context so it
	// stops when Run returns, whether that is a cancelled parent or a rejected
	// config.
	probeCtx, stopProbe := context.WithCancel(ctx)
	probeDone := make(chan struct{})
	go func() {
		defer close(probeDone)
		c.probeDurable(probeCtx, cfg)
	}()
	// Cancel THEN join, in one defer. Two defers would run LIFO — the join first,
	// the cancel second — and the probe only exits on its context, so a Run that
	// returns while the parent context is still alive (a permanently rejected
	// config) would block here until whole-app shutdown, leaking the goroutine and
	// never closing the caller's done channel. Joining after the cancel is still
	// required: an in-flight ConsumerInfo must not outlive Run and land on a
	// connection the caller is about to drain.
	defer func() {
		stopProbe()
		<-probeDone
	}()

	if err := jsconsumer.Run(ctx, c.nc, cfg, func(msg jetstream.Msg) { c.handle(ctx, cfg, msg) }); err != nil {
		// Only a permanently-unacceptable configuration reaches here; Run retries
		// everything it can. Surface it on /readyz and say so loudly — the pod is
		// alive and consuming nothing.
		c.configRejected.Store(true)
		slog.ErrorContext(ctx, "Lifecycle consumer configuration rejected; not consuming",
			slog.String("durable", c.durable), slog.String("subject", c.subject), slog.Any("error", err))
	}
}

// probeDurable keeps lifecycleConsumer.durableBound current until ctx is done. It
// probes immediately, then on a ticker, so a pod does not sit NotReady for a whole
// interval after a healthy start.
//
// The interval is slow on purpose: this is one CONSUMER.INFO per pod per interval
// against every cell's NATS, and /readyz is polled far more often than the answer
// changes — so the probe is cached rather than run per request.
func (c *lifecycleConsumer) probeDurable(ctx context.Context, cfg jsconsumer.Config) {
	js, err := jetstream.New(c.nc)
	// crashes the process, and because the message was never acked JetStream
	// redelivers it — so every replica that picks it up crashes in turn, turning
	// one poison-pill delivery into a cluster-wide crash-loop. Recover and leave
	// the delivery to the server's ladder (bounded by MaxDeliver) instead.
	defer func() {
		if r := recover(); r != nil {
			err := fmt.Errorf("panic recovered in lifecycle handler: %v", r)
			span.RecordError(err)
			span.SetStatus(otelcodes.Error, "handler panic")
			span.SetAttributes(attribute.Bool("entire.handler.panicked", true))
			slog.ErrorContext(ctx, "Recovered panic in lifecycle handler; leaving it for the server ladder (bounded by MaxDeliver)",
				slog.Any("panic", r), slog.String("stack", string(debug.Stack())))
			c.metrics.recordPanic(ctx)
			// No disposition: see the retry-ownership note on lifecycleConsumer.
		}
	}()

	// Attributes Process's prologue does not set. It stamps messaging.system and
	// messaging.destination.name; the operation type and the JetStream
	// coordinates were on this span before the migration and stay on it, so trace
	// queries keyed on them keep working. ClampToInt64 saturates rather than
	// wrapping a sequence past MaxInt64, which the hand-rolled int64() cast here
	// did not.
	span.SetAttributes(attribute.String("messaging.operation.type", "receive"))
	if meta, err := msg.Metadata(); err == nil {
