// Package timingcontract states a consume loop's redelivery timing as data, and
// checks it with go-nuts' exported arithmetic rather than by hand.
//
// # Why the arithmetic is not restated here
//
// ENT-1535 was a consumer whose real redelivery envelope was 34h22m while its
// config advertised 17h45m, and duplicated timing arithmetic is exactly how that
// happens: one number in a comment, another in a config, a third in a runbook,
// and nothing forcing them to agree. [jsconsumer.Schedule] is the single
// implementation — the same function go-nuts runs at consumer construction and
// fleet CI runs over a rendered Consumer CR — so everything below delegates to
// it and adds only a name and a renderer.
//
// A loop states its contract once, next to the constants it is derived from, and
// its test calls [Contract.Validate]. Two loops in this repo cannot be validated
// by jsconsumer.Start itself — cmd/worker and the meta-fanout lifecycle fan carry
// neither a server ladder nor a Retry, so Start's schedule check does not run for
// them — which is precisely why the check has to be reachable from a test.
//
// # The table is generated, not typed
//
// Every Track D migration trail carries a before/after timing table: the old
// effective ladder against the new one. [Markdown] renders it from the same
// Schedule values the test validates, so the table in the trail body cannot drift
// from the ladder in the code. Print it from a test and paste the output.
//
// This package is deliberately pure: no testing import, no NATS connection, no
// clock. It is safe to reference from production code — though today nothing
// does, and a loop that wants its contract at runtime should prefer failing at
// startup through jsconsumer.Start.
package timingcontract

import (
	"fmt"
	"strings"
	"time"

	"github.com/entireio/go-nuts/jsconsumer"
)

// Contract is one consumer's redelivery timing, named so a violation and a table
// row say which loop they are about.
type Contract struct {
	// Name identifies the loop — the durable is the clearest choice, since that
	// is what an operator reads in consumer info and in a KEDA scaler.
	Name string
	// Schedule is the timing itself. Populate it from the loop's real constants,
	// never from literals retyped alongside them: a contract that drifts from the
	// code it describes is the defect this package exists to prevent.
	Schedule jsconsumer.Schedule
}

// Validate reports every way the contract does not hang together, or nil when it
// is coherent. The violations come from [jsconsumer.Schedule.Validate]; only the
// name is added.
func (c Contract) Validate() error {
	if err := c.Schedule.Err(); err != nil {
		return fmt.Errorf("%s: %w", c.Name, err)
	}
	return nil
}

// Unbounded reports whether the consumer never stops redelivering — a
// non-positive MaxDeliver, matching jetstream.ConsumerConfig and
// [jsconsumer.UnlimitedMaxDeliver]. Such a contract has no terminal branch, so
// [Contract.Envelope] and [Contract.CheckEnvelope] have nothing to describe and
// [Markdown] gives it a note instead of a column.
func (c Contract) Unbounded() bool { return c.Schedule.MaxDeliver <= 0 }

// Envelope is the handful of derived numbers a trail, a runbook, and a monitor
// all quote. Pin them in a test so a ladder change that moves any of them has to
// move the documented value with it.
//
// Only meaningful when [Contract.Unbounded] is false: an unbounded consumer has
// no terminal delivery, so the derived numbers degenerate (a negative delivery
// number and a zero duration) rather than describing anything.
type Envelope struct {
	// DeadLetterDelivery is the delivery on which the terminal branch runs —
	// MaxDeliver less any capture reserve. For a loop with no Retry this is just
	// the delivery on which the loop gives up.
	DeadLetterDelivery int
	// TimeToDeadLetter is the cumulative SCHEDULED wait before that delivery.
	// Handler time and a lost delivery's AckWait sit on top of it, so a loop
	// whose handler runs for minutes has a real envelope far longer than this
	// number — cmd/worker is the worked example, and its own test pins the
	// wall-clock bound separately against the stream's max age.
	TimeToDeadLetter time.Duration
	// LongestRung is the largest single wait served before the terminal branch.
	LongestRung time.Duration
}

// Envelope computes the contract's derived numbers.
func (c Contract) Envelope() Envelope {
	return Envelope{
		DeadLetterDelivery: c.Schedule.DeadLetterDelivery(),
		TimeToDeadLetter:   c.Schedule.TimeToDeadLetter(),
		LongestRung:        c.Schedule.LongestRung(),
	}
}

// CheckEnvelope reports how the contract's derived numbers differ from want, or
// nil when they match. Use it to pin the figures a trail or a monitor quotes.
func (c Contract) CheckEnvelope(want Envelope) error {
	got := c.Envelope()
	var diffs []string
	if got.DeadLetterDelivery != want.DeadLetterDelivery {
		diffs = append(diffs, fmt.Sprintf("dead-letter delivery %d, want %d", got.DeadLetterDelivery, want.DeadLetterDelivery))
	}
	if got.TimeToDeadLetter != want.TimeToDeadLetter {
		diffs = append(diffs, fmt.Sprintf("time to dead-letter %s, want %s", got.TimeToDeadLetter, want.TimeToDeadLetter))
	}
	if got.LongestRung != want.LongestRung {
		diffs = append(diffs, fmt.Sprintf("longest rung %s, want %s", got.LongestRung, want.LongestRung))
	}
	if len(diffs) == 0 {
		return nil
	}
	return fmt.Errorf("%s: %s", c.Name, strings.Join(diffs, "; "))
}

// Markdown renders the delivery-by-delivery table a migration trail carries: one
// row per delivery, one column per contract, each cell the cumulative scheduled
// wait by which that delivery arrives. Pass the before and after contracts
// together to get the comparison in a single table.
//
// An unbounded contract ([Contract.Unbounded]) is never given a column: it has no
// terminal delivery, so a cumulative table with a give-up row would be inventing
// one. It gets a note instead, and the bounded contracts still table normally —
// so a mixed before/after comparison reports honestly rather than summarising the
// unbounded side as "gives up on delivery -1 at 0s".
func Markdown(contracts ...Contract) string {
	if len(contracts) == 0 {
		return ""
	}

	var bounded []Contract
	rows := 0
	for _, c := range contracts {
		if c.Unbounded() {
			continue
		}
		bounded = append(bounded, c)
		if c.Schedule.MaxDeliver > rows {
			rows = c.Schedule.MaxDeliver
		}
	}

	var b strings.Builder
	if len(bounded) > 0 {
		b.WriteString("| delivery |")
		for _, c := range bounded {
			fmt.Fprintf(&b, " %s |", c.Name)
		}
		b.WriteString("\n|---:|")
		for range bounded {
			b.WriteString("---|")
		}
		b.WriteString("\n")

		for n := 1; n <= rows; n++ {
			fmt.Fprintf(&b, "| %d |", n)
			for _, c := range bounded {
				b.WriteString(" " + cell(c, n) + " |")
			}
			b.WriteString("\n")
		}
		b.WriteString("\n")
	}

	// Summaries follow the caller's order, so a before/after pair reads in the
	// order it was passed even when one side is unbounded.
	for _, c := range contracts {
		if c.Unbounded() {
			fmt.Fprintf(&b, "- **%s** — unlimited redeliveries: no terminal branch, so no envelope to table.\n", c.Name)
			continue
		}
		e := c.Envelope()
		fmt.Fprintf(&b, "- **%s** — gives up on delivery %d at %s; longest rung %s",
			c.Name, e.DeadLetterDelivery, e.TimeToDeadLetter, e.LongestRung)
		if c.Schedule.StreamMaxAge > 0 {
			fmt.Fprintf(&b, "; stream discards after %s", c.Schedule.StreamMaxAge)
		}
		b.WriteString(".\n")
	}
	return b.String()
}

// cell renders one contract's entry for delivery n: when it arrives, and what
// happens on it. A delivery past this contract's cap is blank rather than zero —
// the two schedules being compared often have different caps, and a "0s" there
// reads as an instant retry.
func cell(c Contract, n int) string {
	if c.Schedule.MaxDeliver > 0 && n > c.Schedule.MaxDeliver {
		return ""
	}
	at := "t+" + c.Schedule.CumulativeTo(n).String()
	switch {
	case n == c.Schedule.DeadLetterDelivery():
		return at + " — give up"
	case c.Schedule.RecoverBy > 0 && n == c.Schedule.RecoverBy:
		return at + " — RecoverBy"
	case c.Schedule.MaxDeliver > 0 && n > c.Schedule.DeadLetterDelivery():
		return at + " — capture reserve"
	default:
		return at
	}
}
