// TestMarkdownRendersLoop2BeforeAfter exercises the renderer on loop 2's real
// before/after pair, so the table format is proven before a trail depends on it —
// and so the arithmetic of the proposed ladder is checked by the library rather
// than by hand.
//
// The "before" contract is MEASURED, not derived from the app's constants. The
// live `webhook-forwarder` durable carries a server-side ladder no source file
// declares (COR-1270): [30s, 2m, 10m, 1h, 4h, 12h, 24h], on prod us-east-2 and
// staging us-west-2 alike, so its real envelope is 41h12m30s rather than the
// 3m30s its own comments describe. Modelling it from the code would restate the
// belief instead of the behaviour, which is the whole failure this package exists
// to prevent.
//
// The "after" contract is the ~40m envelope decided for loop 2 — patient enough
// to absorb an ordinary entire-web deploy without manufacturing manual DLQ
// replay, short enough that a pinned ack floor is a 40-minute exposure rather
// than a 41-hour one. The rung values are a proposal for loop 2's own review;
// what this test pins is that they are coherent and that they hit the decided
// envelope.
//
// AckWait deliberately stays 30s by keeping BackOff[0] at 30s: with a server
// ladder the two are one knob, so lengthening the first rung (entire-search uses
// 5m) would also slow redelivery after a pod dies mid-dispatch, and this
// consumer's handler is a single fast POST behind a one-message prefetch.
func TestMarkdownRendersLoop2BeforeAfter(t *testing.T) {
	t.Parallel()
	before := timingcontract.Contract{
		Name: "before (measured, orphaned ladder)",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{
				30 * time.Second, 2 * time.Minute, 10 * time.Minute,
				time.Hour, 4 * time.Hour, 12 * time.Hour, 24 * time.Hour,
			},
			MaxDeliver: 8,
			AckWait:    30 * time.Second,
		},
	}
	after := timingcontract.Contract{
		Name: "after (declared ~40m ladder)",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{
				30 * time.Second, 2 * time.Minute, 5 * time.Minute,
				12 * time.Minute, 20 * time.Minute,
			},
			MaxDeliver:     7,
			AckWait:        30 * time.Second,
			CaptureReserve: 1,
		},
	}
	for _, c := range []timingcontract.Contract{before, after} {
		if err := c.Validate(); err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
	}

	if err := before.CheckEnvelope(timingcontract.Envelope{
		DeadLetterDelivery: 8,
		TimeToDeadLetter:   41*time.Hour + 12*time.Minute + 30*time.Second,
		LongestRung:        24 * time.Hour,
	}); err != nil {
		t.Errorf("measured envelope drifted from the snapshot taken 2026-08-14: %v", err)
	}
	if err := after.CheckEnvelope(timingcontract.Envelope{
		DeadLetterDelivery: 6,
		TimeToDeadLetter:   39*time.Minute + 30*time.Second,
		LongestRung:        20 * time.Minute,
	}); err != nil {
		t.Errorf("proposed ladder does not hit the decided ~40m envelope: %v", err)
	}

	out := timingcontract.Markdown(before, after)
	t.Logf("rendered timing contract:\n%s", out)

	for _, want := range []string{
		"| delivery |",
		"before (measured, orphaned ladder)",
		"after (declared ~40m ladder)",
		"t+39m30s — give up",
		"t+59m30s — capture reserve",
		"t+41h12m30s — give up",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("rendered table is missing %q:\n%s", want, out)
		}
	}
	// The after contract stops at 7 deliveries; the before contract's 8th row
	// must still render, and the after column must be blank there rather than a
	// zero that would read as an instant retry.
	lines := strings.Split(out, "\n")
	var eighth string
	for _, l := range lines {
		if strings.HasPrefix(l, "| 8 |") {
			eighth = l
		}
	}
	if eighth == "" {
		t.Fatalf("no row for delivery 8:\n%s", out)
	}
	if strings.Count(eighth, "t+") != 1 {
		t.Errorf("delivery 8 should carry a timing only for the before contract, got: %s", eighth)
	}
}

// TestMarkdownHandlesUnlimitedRedeliveries pins that an unbounded consumer
// renders a note rather than a table: it has no terminal branch, so any row count
// would be invented.
func TestMarkdownHandlesUnlimitedRedeliveries(t *testing.T) {
	t.Parallel()
	out := timingcontract.Markdown(timingcontract.Contract{
		Name:     "unbounded",
		Schedule: jsconsumer.Schedule{NakDelay: time.Second, MaxDeliver: jsconsumer.UnlimitedMaxDeliver},
	})
	if strings.Contains(out, "| delivery |") {
		t.Errorf("unlimited consumer rendered a delivery table:\n%s", out)
	}
	if !strings.Contains(out, "unlimited redeliveries") {
		t.Errorf("unlimited consumer did not render its note:\n%s", out)
	}
}

// TestMarkdownMixesBoundedAndUnboundedHonestly is the mixed-comparison regression
// test. It is the realistic migration shape rather than a contrived one: an
// unbounded legacy loop replaced by a bounded one is exactly what trails-fanout
// went through (its `MaxDeliver -1` was retired as a fleet-wide hazard — an
// unreachable destination Nak'd forever and pinned the shared interest stream for
// every consumer on it), so a before/after table will be asked for in that shape.
//
// The bug it pins: an unbounded contract's DeadLetterDelivery is MaxDeliver less
// the capture reserve, i.e. NEGATIVE, and its TimeToDeadLetter is a cumulative
// wait to that non-existent delivery, i.e. zero. Rendered beside a bounded
// contract, that produced a column of timings and the summary "gives up on
// delivery -1 at 0s" — a fabricated terminal schedule presented as migration
// evidence.
func TestMarkdownMixesBoundedAndUnboundedHonestly(t *testing.T) {
	t.Parallel()
	before := timingcontract.Contract{
		Name:     "before (unbounded legacy)",
		Schedule: jsconsumer.Schedule{NakDelay: 30 * time.Second, MaxDeliver: jsconsumer.UnlimitedMaxDeliver},
	}
	after := timingcontract.Contract{
		Name: "after (bounded)",
		Schedule: jsconsumer.Schedule{
			ServerBackOff: []time.Duration{30 * time.Second},
			MaxDeliver:    8,
			AckWait:       30 * time.Second,
		},
	}
	if !before.Unbounded() {
		t.Fatal("the before contract should report as unbounded")
	}
	if after.Unbounded() {
		t.Fatal("the after contract should not report as unbounded")
	}

	out := timingcontract.Markdown(before, after)
	t.Logf("rendered mixed contract:\n%s", out)

	// The bounded side still tables.
	if !strings.Contains(out, "| delivery |") {
		t.Errorf("the bounded contract lost its table in a mixed comparison:\n%s", out)
	}
	if !strings.Contains(out, "t+3m30s — give up") {
		t.Errorf("the bounded contract's give-up row is missing:\n%s", out)
	}
	// The unbounded side gets a note, not a column.
	if !strings.Contains(out, "unlimited redeliveries") {
		t.Errorf("the unbounded contract did not render its note:\n%s", out)
	}
	header := strings.SplitN(out, "\n", 2)[0]
	if strings.Contains(header, before.Name) {
		t.Errorf("the unbounded contract was given a table column: %s", header)
	}
	// And nothing anywhere claims a terminal delivery it does not have.
	for _, forbidden := range []string{"delivery -1", "-1 at"} {
		if strings.Contains(out, forbidden) {
			t.Errorf("rendered output invents a terminal schedule (%q):\n%s", forbidden, out)
		}
	}
}

