package main

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"time"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/trace"

	"github.com/entirehq/mirror-pipeline/internal/mirrorjobs"
)

// mirrorCreatedSubject is the one resource_lifecycle_v1 subject the lifecycle
// consumer acts on (beyond fanning it cross-region): a freshly-created mirror.
// resourceevents publishes <prefix><resource_type>.<op>, so a mirror.created is
// "resource_lifecycle_v1.mirror.created". Matching on the subject lets the
// common case (github_handle / verified_email / the org/project/repo binding
// events that share the bus) skip the JSON decode entirely.
const mirrorCreatedSubject = lifecycleStream + ".mirror.created"

const (
	// lifecycleTypeMirror / lifecycleOpCreated mirror entiredb
	// core/resourceevents' TypeMirror / OpCreated. Re-declared (not imported)
	// to keep meta-fanout free of a Go-module dependency on the entiredb tree —
	// same rationale as the vendored repolookup proto. The payload is validated
	// against these after the subject match as a belt-and-suspenders guard.
	lifecycleTypeMirror = "mirror"
	lifecycleOpCreated  = "created"
)

// lifecycleEvent is the minimal projection of core/resourceevents.Event that
// the mirror.created hook needs. The full envelope carries more (jurisdiction,
// actor, github identity, …); meta-fanout decodes only what it acts on and
// tolerates the rest (unknown JSON fields are ignored).
type lifecycleEvent struct {
	ResourceType string    `json:"resource_type"`
	ResourceID   string    `json:"resource_id"`
	Op           string    `json:"op"`
	Timestamp    time.Time `json:"timestamp"`
}

// mirrorResolver resolves a mirror's repo ULID to its upstream coordinates.
// Satisfied by *mirrorjobs.CoreLookupResolver.
type mirrorResolver interface {
	MirrorByID(ctx context.Context, mirrorID string) (mirrorjobs.MirrorUpstream, error)
}

// maybeSeedMirrorMeta enqueues a github_meta backfill for a newly-created
// mirror so its display metadata (name, description, language, stars) is seeded
// without waiting for a star/fork/repository webhook or a manual backfill run
// (COR-717).
//
// It is deliberately BEST-EFFORT and decoupled from the cross-region fan: a
// failure to decode, resolve, or enqueue is logged + metered but never changes
// the delivery's ack disposition. The verbatim fan is the load-bearing behavior
// of this consumer and must not regress because the backfill stream or the core
// lookup is momentarily unhealthy; the manual `meta-fanout backfill` remains the
// catch-up backstop. Called before the fan so it still runs on a delivery the
// fan will Nak for a remote-region outage; idempotent across that redelivery via
// the backfill dedup id (stable owner/repo + the event's own timestamp).
func (c *lifecycleConsumer) maybeSeedMirrorMeta(ctx context.Context, span trace.Span, subject string, data []byte) {
	// Not wired (e.g. fan-only unit tests, or a deploy that hasn't enabled the
	// hook): nothing to do.
	if c.enqueuer == nil || c.resolver == nil {
		return
	}
	if subject != mirrorCreatedSubject {
		return
	}

	var ev lifecycleEvent
	if err := json.Unmarshal(data, &ev); err != nil {
		slog.WarnContext(ctx, "mirror.created: undecodable lifecycle payload; skipping github_meta seed (fan unaffected)",
			slog.String("subject", subject), slog.Any("error", err))
		c.metrics.recordMirrorSeed(ctx, mirrorSeedError)
		return
	}
	// The subject said mirror.created; require the payload to agree before we
	// act on it. A mismatch means a malformed producer, not our case — skip.
	if ev.ResourceType != lifecycleTypeMirror || ev.Op != lifecycleOpCreated || ev.ResourceID == "" {
		slog.WarnContext(ctx, "mirror.created subject with mismatched payload; skipping github_meta seed",
			slog.String("resource_type", ev.ResourceType),
			slog.String("op", ev.Op),
			slog.Bool("has_resource_id", ev.ResourceID != ""))
		c.metrics.recordMirrorSeed(ctx, mirrorSeedError)
		return
	}
	// observed_at becomes the backfill's monotonic guard AND part of its dedup
	// id. Using the event's own timestamp (not time.Now) keeps a redelivery of
	// the same mirror.created collapsing onto one backfill job. The backfill
	// consumer Terms a zero observed_at, so guard against it here rather than
	// enqueue work that's doomed downstream.
	if ev.Timestamp.IsZero() {
		slog.WarnContext(ctx, "mirror.created without a timestamp; skipping github_meta seed",
			slog.String("mirror_id", ev.ResourceID))
		c.metrics.recordMirrorSeed(ctx, mirrorSeedError)
		return
	}

	span.SetAttributes(attribute.String("entire.mirror.id", ev.ResourceID))

	up, err := c.resolver.MirrorByID(ctx, ev.ResourceID)
	if err != nil {
		if errors.Is(err, mirrorjobs.ErrMirrorNotFound) {
			// The mirror was deleted (or suspended) between creation and our
			// handling — there is nothing to seed. Benign skip.
			span.SetAttributes(attribute.Bool("entire.mirror.unknown_repo", true))
			slog.InfoContext(ctx, "mirror.created for an unknown/suspended mirror; skipping github_meta seed",
				slog.String("mirror_id", ev.ResourceID))
			c.metrics.recordMirrorSeed(ctx, mirrorSeedSkipped)
			return
		}
		slog.WarnContext(ctx, "mirror.created: resolve owner/repo failed; skipping github_meta seed (fan unaffected)",
			slog.String("mirror_id", ev.ResourceID), slog.Any("error", err))
		c.metrics.recordMirrorSeed(ctx, mirrorSeedError)
		return
	}

	job := backfillJob{Owner: up.Owner, Repo: up.Repo, ObservedAt: ev.Timestamp.UTC()}
	span.SetAttributes(
		attribute.String("entire.source_owner", up.Owner),
		attribute.String("entire.source_repo", up.Repo),
	)
	if err := c.enqueuer.Enqueue(ctx, job); err != nil {
		slog.WarnContext(ctx, "mirror.created: enqueue github_meta backfill failed; skipping (fan unaffected)",
			slog.String("mirror_id", ev.ResourceID), slog.String("repo", job.fullName()), slog.Any("error", err))
		c.metrics.recordMirrorSeed(ctx, mirrorSeedError)
		return
	}

	c.metrics.recordMirrorSeed(ctx, mirrorSeedEnqueued)
	slog.InfoContext(ctx, "Enqueued github_meta backfill for newly-created mirror",
		slog.String("mirror_id", ev.ResourceID), slog.String("repo", job.fullName()))
}

