// CoreLookupResolver resolves GitHub mirrors through entire-core RepoLookup.
type CoreLookupResolver struct {
	client RepoLookupClient
	skips  metric.Int64Counter
}

// NewCoreLookupResolver returns a RepoLookup-backed route resolver.
func NewCoreLookupResolver(client RepoLookupClient) *CoreLookupResolver {
	// placement_skipped counts placements dropped from a lookup because a
	// required routing field was blank, tagged by reason — an alertable signal
	// that entire-core returned unroutable placement data (otherwise only a WARN
	// log). Built here, after otel setup in main, so it binds to the real meter
	// provider rather than the startup no-op.
	skips, _ := otel.Meter("github.com/entirehq/mirror-pipeline/internal/mirrorjobs").
		Int64Counter("mirrorjobs.placement_skipped",
			metric.WithDescription("Placements dropped from a repo lookup because a required routing field (cluster_slug or repo_id) was blank or malformed, by reason."))
	return &CoreLookupResolver{client: client, skips: skips}
}

// recordSkip increments the placement_skipped counter with a reason label.
// Safe when the counter failed to register (nil).
func (r *CoreLookupResolver) recordSkip(ctx context.Context, reason string) {
	if r.skips != nil {
		r.skips.Add(ctx, 1, metric.WithAttributes(attribute.String("reason", reason)))
	}
}

// RoutesForSource resolves a source event into target mirror routes.
func (r *CoreLookupResolver) RoutesForSource(ctx context.Context, event SourceEvent) ([]MirrorRoute, error) {
	if event.Kind != gitjobs.SourceKindGithub {
		return nil, fmt.Errorf("unsupported source kind %q", event.Kind)
	}

	resp, err := r.client.LookupByMirror(ctx, connect.NewRequest(&repolookupv1.LookupByMirrorRequest{
		Provider: string(gitjobs.SourceKindGithub),
		Owner:    event.Owner,
		Repo:     event.Repo,
	}))
	if err != nil {
		return nil, fmt.Errorf("repo lookup: %w", err)
	}

// MirrorUpstream is the upstream identity of a mirror, resolved from its repo
// ULID via RepoLookup.LookupMirrorByID — the inverse of RoutesForSource.
type MirrorUpstream struct {
	Provider string
	Owner    string
	Repo     string
}

// MirrorByID resolves a mirror's repo ULID to its upstream coordinates. It
// backs meta-fanout's mirror.created hook: the resource_lifecycle_v1 event
// carries only the mirror ULID, so the (owner, repo) needed to enqueue a
// github_meta backfill must be re-queried from entire-core.
//
// ErrMirrorNotFound is returned for an unknown (or suspended) mirror ULID so
// the caller can treat it as a benign skip rather than a transient failure to
// retry.
func (r *CoreLookupResolver) MirrorByID(ctx context.Context, mirrorID string) (MirrorUpstream, error) {
	if mirrorID == "" {
		return MirrorUpstream{}, errors.New("mirror id is required")
	}

	resp, err := r.client.LookupMirrorByID(ctx, connect.NewRequest(&repolookupv1.LookupMirrorByIDRequest{
		RepoId: mirrorID,
	}))
	if err != nil {
		if connect.CodeOf(err) == connect.CodeNotFound {
			return MirrorUpstream{}, fmt.Errorf("%w: %s", ErrMirrorNotFound, mirrorID)
		}
		return MirrorUpstream{}, fmt.Errorf("lookup mirror by id %s: %w", mirrorID, err)
	}

	return MirrorUpstream{
		Provider: resp.Msg.GetProvider(),
		Owner:    resp.Msg.GetOwner(),
		Repo:     resp.Msg.GetRepo(),
	}, nil
}
