// Real-broker coverage for the lifecycle fan's migration onto jsconsumer
// (COR-1254, loop 1). The unit tests above assert what the handler DOES — which
// disposition it chose. These assert what the BROKER does about it, which is the
// half a fake cannot answer: the fakes encode the same model as the code, so a
// belief held wrongly in both places produces a green test.
//
// Two of this migration's three load-bearing beliefs are broker facts:
//
//  1. the config the app renders is the config the durable ends up with —
//     CreateOrUpdateConsumer sends every field, so a field omitted in code is not
//     "left alone", it is reset;
//  2. leaving a failed delivery UNSETTLED gets it redelivered on the durable's
//     ladder — the whole basis for dropping the client-side NakWithDelay.
//
// The third (that a ladder disagreeing with AckWait is silently rewritten) is
// pinned in internal/natstest, since it is a property of the server rather than of
// this consumer.

// lifecycleTestStream mirrors the fleet-provisioned stream this consumer reads:
// limits retention (an idle durable pins nothing, which is why it carries no
// InactiveThreshold) and a max age far longer than the ladder, so jsconsumer's
// retention check passes for the reason it should rather than by accident.
func lifecycleTestStream() jetstream.StreamConfig {
	return jetstream.StreamConfig{
		Name:       lifecycleStream,
		Subjects:   []string{lifecycleStream + ".>"},
		Retention:  jetstream.LimitsPolicy,
		MaxAge:     96 * time.Hour,
		Duplicates: 2 * time.Minute,
	}
}

// TestLifecycleDurable_StoredConfigIsTheRenderedConfig is the executable form of
// this migration's pre-flight: it drives the REAL lifecycleConsumerConfig through
// the real CreateOrUpdateConsumer and reads back what the server stored.
//
// The seven live durables were snapshotted before this change (ackWait 30s,
// maxDeliver 8, no backoff, no inactiveThreshold, maxAckPending 65536), so the
// intended delta is exactly two fields: the ladder appears, and maxAckPending
// becomes a number somebody chose. Everything else must land unchanged, and this
// is what proves the rendered config says so.
func TestLifecycleDurable_StoredConfigIsTheRenderedConfig(t *testing.T) {
	t.Parallel()
	nc, js := natstest.Env(t, lifecycleTestStream())

	cfg := lifecycleConsumerConfig(lifecycleDurable, lifecycleSubjectFilter)
	runner, err := jsconsumer.Start(t.Context(), nc, cfg, func(jetstream.Msg) {})
	if err != nil {
		t.Fatalf("start the lifecycle consumer against a real broker: %v", err)
	}
	t.Cleanup(runner.Stop)

	stream, err := js.Stream(t.Context(), lifecycleStream)
	if err != nil {
		t.Fatalf("stream handle: %v", err)
	}
	cons, err := stream.Consumer(t.Context(), lifecycleDurable)
	if err != nil {
		t.Fatalf("consumer handle: %v", err)
	}
	got := natstest.Info(t, cons).Config

	if got.AckWait != consumerAckWait {
		t.Errorf("stored AckWait = %v, want %v", got.AckWait, consumerAckWait)
	}
	if got.MaxDeliver != consumerMaxDeliver {
		t.Errorf("stored MaxDeliver = %d, want %d", got.MaxDeliver, consumerMaxDeliver)
	}
	if got.MaxAckPending != lifecycleMaxAckPending {
		t.Errorf("stored MaxAckPending = %d, want the value this migration chose (%d)", got.MaxAckPending, lifecycleMaxAckPending)
	}
	if got.FilterSubject != lifecycleSubjectFilter {
		t.Errorf("stored FilterSubject = %q, want %q", got.FilterSubject, lifecycleSubjectFilter)
	}
	if got.AckPolicy != jetstream.AckExplicitPolicy {
		t.Errorf("stored AckPolicy = %v, want explicit", got.AckPolicy)
	}
	// The 2026-06-01 reaping valve is for interest streams; this one is limits, so
	// no threshold is wanted and none may appear by default.
	if got.InactiveThreshold != 0 {
		t.Errorf("stored InactiveThreshold = %v, want none on a limits-retention stream", got.InactiveThreshold)
	}
	want := lifecycleBackOff()
	if len(got.BackOff) != len(want) {
		t.Fatalf("stored BackOff has %d rungs, want %d", len(got.BackOff), len(want))
	}
	for i := range want {
		if got.BackOff[i] != want[i] {
			t.Errorf("stored BackOff[%d] = %v, want %v", i, got.BackOff[i], want[i])
		}
	}
	// The ladder must have somewhere to apply every rung, and the schedule as a
	// whole must hang together. jsconsumer.Start already refused an incoherent one
	// to get here; asserting it explicitly names what "coherent" bought us.
	if err := lifecycleSchedule().Err(); err != nil {
		t.Errorf("the shipped schedule is incoherent: %v", err)
	}
}

// TestLifecycleFanFailure_IsRedeliveredByTheServerLadder pins the belief that
// replaced the client-side NakWithDelay: a handler that settles NOTHING gets its
// delivery back, paced by the durable's BackOff.
//
// The ladder here is SCALED (milliseconds, not the shipped 30s) and — importantly
// — GROWING. A flat ladder would make BackOff[0] and AckWait the same number, so
// the test would pass whether redelivery followed the ladder or merely the ack
// timeout, pinning nothing. Growing rungs separate the two: the second gap can
// only come from BackOff[1]. The shipped ladder is deliberately flat, so on it the
// two coincide — which is a property of that ladder, not of the mechanism.
func TestLifecycleFanFailure_IsRedeliveredByTheServerLadder(t *testing.T) {
	t.Parallel()
	nc, _ := natstest.Env(t, lifecycleTestStream())

	const rung1, rung2 = 200 * time.Millisecond, 900 * time.Millisecond
	cfg := lifecycleConsumerConfig(lifecycleDurable, lifecycleSubjectFilter)
	cfg.AckWait = rung1 // must equal BackOff[0]; the server stores it that way regardless
	cfg.BackOff = []time.Duration{rung1, rung2}
	cfg.MaxDeliver = 3

	// A remote that always fails, so every delivery takes dispatch's do-nothing
	// branch. The remotes are publish handles, not brokers, so they stay fakes.
	// recordingJS is not usable here: it records only SUCCESSFUL publishes, so its
	// count would read zero however many times the fan was attempted.
	broken := &failingJS{err: errors.New("region down")}
	c := &lifecycleConsumer{
		nc:      nc,
		fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{"eu": broken}, localClusterID: "us"},
		durable: lifecycleDurable,
		subject: lifecycleSubjectFilter,
	}

	arrivals := make(chan time.Time, 8)
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	runner, err := jsconsumer.Start(ctx, nc, cfg, func(msg jetstream.Msg) {
		// Timestamp at delivery, publish to the channel only AFTER the handler has
		// run. Sending first would let the test collect its last arrival while
		// that delivery's fan was still in flight, and then assert on a count
		// that had not happened yet.
		at := time.Now()
		c.handle(ctx, cfg, msg)
		arrivals <- at
	})
	if err != nil {
		t.Fatalf("start: %v", err)
	}
	defer runner.Stop()

	natstest.Publish(t, natstest.JetStream(t, nc), lifecycleStream+".github_handle.created", lifecycleBody)

	got := make([]time.Time, 0, 3)
	deadline := time.After(15 * time.Second)
	for len(got) < 3 {
		select {
		case at := <-arrivals:
			got = append(got, at)
		case <-deadline:
			t.Fatalf("saw %d deliveries in 15s, want 3: an unsettled delivery is not being redelivered", len(got))
		}
	}

	// Gap tolerance is half the distance to the nearest rival explanation, so the
	// assertion cannot accept the wrong one. Rival for gap 1 is ~0 (an immediate
	// redelivery, i.e. a plain Nak); for gap 2 it is rung1 (the ladder not
	// advancing).
	assertGap(t, "first redelivery", got[1].Sub(got[0]), rung1, rung1/2)
	assertGap(t, "second redelivery", got[2].Sub(got[1]), rung2, (rung2-rung1)/2)

	// Every redelivery must have re-run the fan, not merely re-entered the handler:
	// a redelivery that skipped the publish would still produce the gaps above.
	if got := broken.attempts(); got < 3 {
		t.Errorf("the fan was attempted %d times, want one per delivery (3)", got)
	}
}

// failingJS is a remote publish handle that always fails and counts every
// ATTEMPT. recordingJS records only successful publishes, which makes it blind to
// exactly the path this file exercises.
type failingJS struct {
	mu  sync.Mutex
	n   int
	err error
}

func (f *failingJS) PublishMsg(_ context.Context, _ *nats.Msg, _ ...jetstream.PublishOpt) (*jetstream.PubAck, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.n++
	return nil, f.err
}

func (f *failingJS) attempts() int {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.n
}

// assertGap fails unless observed is within tolerance of want. tolerance is the
// caller's, because only the caller knows how far the nearest rival explanation
// sits — a band wider than that accepts the behaviour the test was written to
// reject.
func assertGap(t *testing.T, label string, observed, want, tolerance time.Duration) {
	t.Helper()
	delta := observed - want
	if delta < 0 {
		delta = -delta
	}
	if delta > tolerance {
		t.Errorf("%s came after %v, want %v ±%v", label, observed, want, tolerance)
	}
}

// TestLifecycleCleanFan_AdvancesTheAckFloor pins the success path against a real
// broker: an Acked delivery settles, so the durable's ack floor moves and nothing
// is left pending.
//
// The floor is the signal every stall alert on these streams reads, and it is the
// one thing a fake cannot show — natsmsgtest.FakeMsg records that Ack was called,
// never that the server accepted it. A denied $JS.ACK publish returns no error at
// all (COR-1224), so "we called Ack" and "the message is settled" are genuinely
// different claims.
func TestLifecycleCleanFan_AdvancesTheAckFloor(t *testing.T) {
	t.Parallel()
	nc, js := natstest.Env(t, lifecycleTestStream())

	cfg := lifecycleConsumerConfig(lifecycleDurable, lifecycleSubjectFilter)
	cfg.AckWait = 2 * time.Second
	cfg.BackOff = []time.Duration{2 * time.Second}
	cfg.MaxDeliver = 3

	eu := &recordingJS{}
	c := &lifecycleConsumer{
		nc:      nc,
		fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{"eu": eu}, localClusterID: "us"},
		durable: lifecycleDurable,
		subject: lifecycleSubjectFilter,
	}

	done := make(chan struct{}, 1)
	ctx, cancel := context.WithCancel(t.Context())
	defer cancel()
	runner, err := jsconsumer.Start(ctx, nc, cfg, func(msg jetstream.Msg) {
		c.handle(ctx, cfg, msg)
		select {
		case done <- struct{}{}:
		default:
		}
	})
	if err != nil {
		t.Fatalf("start: %v", err)
	}
	defer runner.Stop()

	natstest.Publish(t, js, lifecycleStream+".github_handle.created", lifecycleBody)
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatal("the delivery never reached the handler")
	}
	}

	stream, err := js.Stream(t.Context(), lifecycleStream)
	if err != nil {
		t.Fatalf("stream handle: %v", err)
	}
	cons, err := stream.Consumer(t.Context(), lifecycleDurable)
	if err != nil {
		t.Fatalf("consumer handle: %v", err)
	}
	// The ack is fire-and-forget, so poll rather than read once: a single read can
	// land between the handler returning and the server recording the ack.
	deadline := time.Now().Add(5 * time.Second)
	for {
		info := natstest.Info(t, cons)
		if info.AckFloor.Stream == 1 && info.NumAckPending == 0 && info.NumPending == 0 {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("ack floor did not advance: floor=%d ack_pending=%d pending=%d",
				info.AckFloor.Stream, info.NumAckPending, info.NumPending)
		}
		time.Sleep(20 * time.Millisecond)
	}

	if eu.count() != 1 {
		t.Errorf("the remote region received %d publishes, want 1", eu.count())
	}
}

// TestLifecycleReadiness_FollowsTheDurable is the regression test for the
// /readyz finding on trail #102.
//
// jsconsumer.Run retries every failure it can and returns only on a permanently
// rejected config, so a readiness gate built on that alone stays green through the
// outages it exists to report: a stream not provisioned yet, or a JetStream API
// unreachable while the TCP connection is up. The pre-existing natsregions check
// does not cover either (it asks IsConnected only), and in lifecycle-only mode this
// consumer is the pod's SOLE gate — so green there hides a real outage.
//
// Both directions are asserted, because only one of them fails if the probe is
// deleted: NotReady before the durable exists, Ready once it does.
func TestLifecycleReadiness_FollowsTheDurable(t *testing.T) {
	t.Parallel()
	// A broker with NO stream: the declarative-provisioning race, and the case the
	// old `subscribed` bool reported and configRejected does not.
	nc, _ := natstest.Connect(t, natstest.Server(t))
	c := &lifecycleConsumer{
		nc:      nc,
		fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{}, localClusterID: "us"},
		durable: lifecycleDurable,
		subject: lifecycleSubjectFilter,
	}

	if c.Ready() {
		t.Error("a consumer that has never probed must report NotReady")
	}

	cfg := lifecycleConsumerConfig(lifecycleDurable, lifecycleSubjectFilter)
	js := natstest.JetStream(t, nc)

	if c.durableReachable(t.Context(), js, cfg, true /* inStartupGrace */) {
		t.Error("the durable reported reachable with no stream provisioned")
	}
	c.durableBound.Store(c.durableReachable(t.Context(), js, cfg, true /* inStartupGrace */))
	if c.Ready() {
		t.Error("Ready() is true while the stream does not exist — this is the outage /readyz must surface")
	}

	// Provision the stream and the durable, exactly as the app would.
	natstest.Stream(t, js, lifecycleTestStream())
	runner, err := jsconsumer.Start(t.Context(), nc, cfg, func(jetstream.Msg) {})
	if err != nil {
		t.Fatalf("start: %v", err)
	}
	t.Cleanup(runner.Stop)

	if !c.durableReachable(t.Context(), js, cfg, true /* inStartupGrace */) {
		t.Fatal("the durable reported unreachable after it was created")
	}
	c.durableBound.Store(true)
	if !c.Ready() {
		t.Error("Ready() is false with a live durable and an accepted config")
	}

	// And a permanently rejected config still overrides a reachable durable.
	c.configRejected.Store(true)
	if c.Ready() {
		t.Error("Ready() must stay false once the configuration was rejected")
	}
}

// TestLifecycleReadiness_ProbeRunsUnderRun pins that Run actually starts the probe
// and that it converges — the wiring, not just the helper. Without this, deleting
// the goroutine from Run would leave every assertion above still passing.
func TestLifecycleReadiness_ProbeRunsUnderRun(t *testing.T) {
	t.Parallel()
	nc, js := natstest.Env(t, lifecycleTestStream())
	c := &lifecycleConsumer{
		nc:      nc,
		fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{}, localClusterID: "us"},
		durable: lifecycleDurable,
		subject: lifecycleSubjectFilter,
	}
	_ = js

	ctx, cancel := context.WithCancel(t.Context())
	done := make(chan struct{})
	go func() {
		defer close(done)
		c.Run(ctx)
	}()

	deadline := time.Now().Add(10 * time.Second)
	for !c.Ready() {
		if time.Now().After(deadline) {
			cancel()
			<-done
			t.Fatal("Ready() never became true under Run: the readiness probe is not wired")
		}
		time.Sleep(20 * time.Millisecond)
	}

	// Run must also join the probe on the way out, so no ConsumerInfo is in flight
	// on a connection the caller is about to drain.
	cancel()
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatal("Run did not return after its context was cancelled")
	}
}

// TestLifecycleRun_ReturnsOnRejectedConfig covers the path the probe-join defer
// used to deadlock on (review finding on trail #102).
//
// Two defers would run LIFO — join first, cancel second — and the probe exits only
// on its context, so a Run that returned while the PARENT context was still alive
// blocked forever: goroutine leaked, caller's done channel never closed, and the
// probe kept polling. Only a permanently rejected config reaches that path, which
// is why the happy-path tests never saw it.
//
// The rejection here is the real-world one this migration risks: a durable that
// already exists with an immutable field set differently, so CreateOrUpdateConsumer
// fails in a way jsconsumer classifies as permanent rather than retrying.
func TestLifecycleRun_ReturnsOnRejectedConfig(t *testing.T) {
	t.Parallel()
	nc, js := natstest.Env(t, lifecycleTestStream())

	// Pre-create the durable with an immutable field the app's config disagrees
	// with. AckPolicy cannot be updated, so the app's create is rejected outright.
	natstest.Consumer(t, js, lifecycleStream, jetstream.ConsumerConfig{
		Durable:       lifecycleDurable,
		AckPolicy:     jetstream.AckNonePolicy,
		FilterSubject: lifecycleSubjectFilter,
	})

	c := &lifecycleConsumer{
		nc:      nc,
		fanout:  &lifecycleFanout{remotes: map[string]metajobs.JetStreamPublisher{}, localClusterID: "us"},
		durable: lifecycleDurable,
		subject: lifecycleSubjectFilter,
	}

	// Parent context stays ALIVE for the whole test: that is the condition the bug
	// needed, and cancelling would mask it.
	done := make(chan struct{})
