	// or above the steady one is not a burst, a zero bound removes the phase the
	// create race needs, and a burst measured in minutes would be no better than an
	// unbounded one for log volume.
	if lifecycleReadyProbeStartupInterval >= lifecycleReadyProbeInterval {
		t.Errorf("startup interval %v is not faster than the steady %v",
			lifecycleReadyProbeStartupInterval, lifecycleReadyProbeInterval)
	}
	if lifecycleReadyProbeStartupAttempts <= 0 {
		t.Errorf("startup attempts = %d, want a positive bound", lifecycleReadyProbeStartupAttempts)
	}
