  cmd: "rg -n \"apps/nats|nats/overlays|nats/base\" fleet/clusters/nonprod fleet/clusters/prod -g 'kustomization.yaml' -g '*.yaml' | head -200",
  workdir: "/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "rg -n \"JSApiStreamInfoT|STREAM\\.INFO|apiSubj.*StreamInfo|StreamInfo\" mirror-pipeline/vendor/github.com/nats-io/nats.go/jetstream -g '*.go' | head -120",
  workdir: "/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms: 10000,
  max_output_tokens: 10000
});
text(r.output);

const paths = [
  "fleet/apps/nats/base",
  "fleet/apps/nats/overlays/eks-prod-us-east-2",
