  }),
  tools.exec_command({
    cmd: "gh api 'repos/entirehq/fleet/commits?path=apps/mirror-pipeline/meta-fanout&per_page=10' --jq '.[] | {sha: .sha, date: .commit.committer.date, message: .commit.message}'",
