const c = await tools.exec_command({
  cmd:"gh api repos/entirehq/fleet/commits/30b2d558610cb5094c48187b670507f03d6b8994 --jq '{message: .commit.message, files: [.files[] | {filename,status,patch}]}'",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:30000,
  max_output_tokens:20000,
  sandbox_permissions:"require_escalated",
  justification:"May I inspect the Fleet deploy commit to determine exactly which seven overlays were updated?",
  prefix_rule:["gh","api"]
});
text(c.output);

const fs = await tools.exec_command({
  cmd:"rg --files fleet/apps/mirror-pipeline/meta-fanout fleet/.github/workflows | head -120",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:10000,
  max_output_tokens:10000
});
const status = await tools.exec_command({
  cmd:"git -C fleet status --short --branch",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:10000,
  max_output_tokens:4000
});
text(fs.output); text(status.output);

const fetch = await tools.exec_command({
  cmd:"git fetch origin main",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:30000,
  max_output_tokens:5000,
  sandbox_permissions:"require_escalated",
  justification:"May I refresh the local Fleet checkout so rollout monitoring uses the current promotion workflow and overlays?",
  prefix_rule:["git","fetch","origin"]
});
text(fetch.output);

const wf = await tools.exec_command({
  cmd:"git show origin/main:.github/workflows/promote.yml | sed -n '1,260p'",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:10000,
  max_output_tokens:20000
});
const dep = await tools.exec_command({
  cmd:"git show origin/main:.github/workflows/deploy.yml | sed -n '1,260p'",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:10000,
  max_output_tokens:20000
});
text(wf.output); text(dep.output);

const files = await tools.exec_command({
  cmd:"rg -n -C 8 'meta-fanout|prod_targets|promote' .github/workflows",
  workdir:"/Users/nodo/work/tasks/nats-robustness/mirror-pipeline",
  yield_time_ms:10000,
  max_output_tokens:20000
});
text(files.output);

const s = await tools.exec_command({
  cmd:"sleep 15",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:20000,
  max_output_tokens:1000
});
const r = await tools.exec_command({
  cmd:"gh run view 32011851197 -R entirehq/mirror-pipeline --json status,conclusion,jobs --jq '{status,conclusion,meta: [.jobs[] | select(.name | contains(\"meta-fanout\")) | {name,status,conclusion,startedAt,completedAt,url,activeSteps: [.steps[] | select(.status != \"completed\") | {name,status,conclusion}]}]}'",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:30000,
  max_output_tokens:12000,
  sandbox_permissions:"require_escalated",
  justification:"May I keep polling the deployment and promotion jobs until the meta-fanout rollout advances?",
  prefix_rule:["gh","run","view"]
});
text(r.output);

const k = await tools.exec_command({
  cmd:"kubectl config get-contexts -o name",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:10000,
  max_output_tokens:10000
});
text(k.output);

const contexts = ["eks-staging-us-west-2","eks-staging-eu-west-1","eks-staging-us-east-2"];
const rs = await Promise.all(contexts.map(ctx => tools.exec_command({
  cmd:`kubectl --context ${ctx} -n meta-fanout get deployment meta-fanout -o json`,
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:30000,
  max_output_tokens:20000,
  sandbox_permissions:"require_escalated",
  justification:`May I read the meta-fanout deployment status in ${ctx} to monitor the staging rollout?`
})));
for (let i=0;i<rs.length;i++) text(JSON.stringify({context:contexts[i],exit_code:rs[i].exit_code,output:rs[i].output}));

