const contexts = ["eks-staging-us-west-2","eks-staging-eu-west-1","eks-staging-us-east-2","eks-prod-us-east-2","eks-prod-eu-central-1","eks-prod-ap-southeast-2","eks-prod-ap-south-1"];
const calls = [];
for (const ctx of contexts) {
  calls.push(tools.exec_command({
    cmd:`kubectl --context ${ctx} -n meta-fanout get deployment meta-fanout -o json`,
    workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:12000,
    sandbox_permissions:"require_escalated",justification:`May I inspect current meta-fanout availability in ${ctx} after finding the AP South readiness failure?`
  }));
  calls.push(tools.exec_command({
    cmd:`kubectl --context ${ctx} -n meta-fanout logs -l app=meta-fanout --all-containers=true --prefix=true --since=10m --tail=1000`,
    workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:20000,
    sandbox_permissions:"require_escalated",justification:`May I scan recent meta-fanout logs in ${ctx} for the same lifecycle consumer failure?`
  }));
}
const rs = await Promise.all(calls);
const patterns = [
  "consumer deleted","Lifecycle durable unreachable","configuration rejected",
  "consume loop closed","no heartbeat received","no responders available","Lifecycle fan failed"
];
for (let i=0;i<contexts.length;i++) {
  let depSummary={};
  try {
    const d=JSON.parse(rs[i*2].output);
    depSummary={
      tag:d.metadata?.annotations?.["fleet.entire.io/source-tag"],
      generation:`${d.metadata?.generation}/${d.status?.observedGeneration}`,
      replicas:d.status?.replicas||0, updated:d.status?.updatedReplicas||0,
      ready:d.status?.readyReplicas||0, available:d.status?.availableReplicas||0,
      unavailable:d.status?.unavailableReplicas||0
    };
  } catch(e) { depSummary={parse_error:String(e),raw:rs[i*2].output.slice(0,300)}; }
  const lines=rs[i*2+1].output.split("\n").filter(Boolean);
  const counts={};
  for (const p of patterns) counts[p]=lines.filter(l=>l.includes(p)).length;
  const relevant=lines.filter(l=>patterns.some(p=>l.includes(p))).slice(-6);
  text(JSON.stringify({context:contexts[i],deployment:depSummary,signals:counts,latest:relevant}));
}

