// durableReachable reports whether the durable answers on the server, and routes
// the outcome through natslog.Health. A bounded timeout of its own, so a probe
// cannot hang past the interval and stall the readiness signal at a stale value.
//
// Health is what restores the supervision the hand-rolled loop had and
// jsconsumer.Run does not provide: Run logs every retryable failure at WARN
// forever, with no counter and no escalation, so a sustained outage looked exactly
// like deploy churn. Routing the probe through Health brings back both halves —
// the nats.consumer.recoverable_failures counter (restart-proof, for the
// pods-cycling-faster-than-escalation case) and the return to ERROR level after
// five minutes without recovery.
//
// This matters most where /readyz cannot help. In US/default mode the readiness
// gate deliberately excludes this consumer, so that a problem here cannot stall
// the live github_meta fan-out — which means a stopped lifecycle fan in US shows up
// ONLY in telemetry. The probe is the signal; Health is what makes it page.
func (c *lifecycleConsumer) durableReachable(ctx context.Context, js jetstream.JetStream, cfg jsconsumer.Config, inStartupGrace bool) bool {
	probeCtx, cancel := context.WithTimeout(ctx, lifecycleReadyProbeTimeout)
	defer cancel()
	if _, err := js.Consumer(probeCtx, cfg.Stream, cfg.Durable); err != nil {
		// Our own teardown first. Run cancels the probe's context on the way out, so
		// a request in flight at that moment comes back context.Canceled — which is
		// NOT in the transient set, so routing it to Health logged an ERROR on every
		// rollout. That is the self-inflicted shutdown noise natslog exists to remove
		// (COR-1228: 57 ErrNoResponders in 83ms during a deploy, three false alerts
		// in forty minutes), reintroduced by the thing meant to report real outages.
		//
		// Deliberately narrow: BOTH the parent being done AND the error being
		// Canceled. A context.DeadlineExceeded from this probe's own timeout leaves
		// the parent alive and still reaches Health, as do consumer-deletion and
		// stream-missing errors — the same discipline as nuts.IsShutdownFetchErr,
		// which is only willing to call a drain benign when ctx is already done.
		if ctx.Err() != nil && errors.Is(err, context.Canceled) {
			slog.DebugContext(ctx, "Lifecycle readiness probe cancelled during shutdown",
				slog.String("durable", cfg.Durable))
			return false
		}
		// A missing durable means different things at different times, and only the
		// probe loop knows which — hence inStartupGrace rather than a judgement from
		// the error value.
		//
		// Inside the grace it is the startup race with jsconsumer.Run creating the
		// durable: expected, Run logs its own attempts, and reporting it through
		// Health would manufacture a failure run out of normal boot.
		//
		// Outside the grace it is one of two real problems, both loud: the durable
		// never got created (creation failing while INFO answers not-found), or it
		// disappeared after binding — which natslog keeps loud on purpose, because
		// the supervisor recreates it from the stream's DeliverPolicy (all), losing
		// the cursor and re-fanning whatever resource_lifecycle_v1 still retains, up
		// to 96h in prod. The was_bound attribute tells the two apart in the log;
		// the severity is the same because both need somebody to look.
		//
		// Honest limit: at a 5s cadence this probe can miss a delete that Run
		// recreates before the next tick, so it is a backstop rather than a
		// detector. The reliable signal is the runner's own recreate, which
		// jsconsumer only logs — recorded with the other go-nuts follow-ups this
		// migration accumulated.
		if inStartupGrace && isDurableMissing(err) {
			slog.DebugContext(ctx, "Lifecycle durable not created yet; reporting NotReady",
				slog.String("stream", cfg.Stream), slog.String("durable", cfg.Durable), slog.Any("error", err))
			return false
		}
		// SubscribeErr, not Err: this is the create/bind path, which absorbs two
		// failures a fetch path must not — a JetStream API slow to answer, and the
		// stream not existing yet (rollout ordering, kept at warn however long it
		// lasts and excluded from escalation).
		c.health.SubscribeErr(ctx, "Lifecycle durable unreachable; reporting NotReady", err,
			slog.String("stream", cfg.Stream), slog.String("durable", cfg.Durable),
			slog.Bool("was_bound", c.everBound.Load()))
		return false
	}
	c.health.Recovered()
	return true
}

// isDurableMissing reports whether err says the consumer does not exist. The
// server answers with either spelling depending on which API surface was asked
// (404 ErrConsumerNotFound, 400 ErrConsumerDoesNotExist), so both are matched.
func isDurableMissing(err error) bool {
	return errors.Is(err, jetstream.ErrConsumerNotFound) ||
		errors.Is(err, jetstream.ErrConsumerDoesNotExist)
}

// handle is the per-message entry point — the production callback and the seam
// tests drive, so the span prologue is exercised the same way in both.
func (c *lifecycleConsumer) handle(ctx context.Context, cfg jsconsumer.Config, msg jetstream.Msg) {
	jsconsumer.Process(ctx, msg, cfg, passthroughPayload,
		func(ctx context.Context, span trace.Span, msg jetstream.Msg, data []byte) {
			c.dispatch(ctx, span, msg.Subject(), data, msg.Headers(), msg)
		},
		nil, // unreachable: passthroughPayload cannot fail, so nothing is ever undecodable
	)
}

// passthroughPayload is the lifecycle fan's "decoder". The event is republished
// verbatim — subject and bytes untouched — so there is nothing to decode and no
// payload that can fail to. Process still earns its place: it opens the consumer
// span re-parented to the producer across the NATS hop.
func passthroughPayload(b []byte) ([]byte, error) { return b, nil }

