const goal = await tools.get_goal({});
const contexts = ["eks-staging-us-west-2","eks-staging-eu-west-1","eks-staging-us-east-2","eks-prod-us-east-2","eks-prod-eu-central-1","eks-prod-ap-southeast-2","eks-prod-ap-south-1"];
const rs = await Promise.all(contexts.map(ctx => tools.exec_command({
  cmd:`kubectl --context ${ctx} -n meta-fanout get deployment meta-fanout -o json`,
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:12000,
  sandbox_permissions:"require_escalated",justification:`May I continue reading meta-fanout rollout health in ${ctx}?`
})));
text(JSON.stringify(goal));
for (let i=0;i<contexts.length;i++) {
  try {
    const d=JSON.parse(rs[i].output);
    text(JSON.stringify({context:contexts[i],
      tag:d.metadata?.annotations?.["fleet.entire.io/source-tag"],
      generation:`${d.metadata?.generation}/${d.status?.observedGeneration}`,
      replicas:d.status?.replicas||0,updated:d.status?.updatedReplicas||0,
      ready:d.status?.readyReplicas||0,available:d.status?.availableReplicas||0,
      unavailable:d.status?.unavailableReplicas||0,
      conditions:(d.status?.conditions||[]).map(c=>({type:c.type,status:c.status,reason:c.reason,lastTransitionTime:c.lastTransitionTime,message:c.message}))
    }));
  } catch(e) { text(JSON.stringify({context:contexts[i],error:rs[i].output})); }
}

