const now = await tools.exec_command({cmd:"date -u '+%Y-%m-%dT%H:%M:%SZ'",workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:10000,max_output_tokens:1000});
const pods = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout get pods -l app=meta-fanout -o json",
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:12000,
  sandbox_permissions:"require_escalated",justification:"May I verify the exact AP South pod names and current restart/readiness state before proposing recovery?"
});
const logs = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout logs -l app=meta-fanout --all-containers=true --prefix=true --since=20m --tail=1000",
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:24000,
  sandbox_permissions:"require_escalated",justification:"May I verify whether AP South has produced any recovery signal since the durable disappeared?"
});
text(now.output);
try {
  const p=JSON.parse(pods.output);
  text(JSON.stringify((p.items||[]).map(x=>({
    name:x.metadata.name,created:x.metadata.creationTimestamp,
    phase:x.status.phase,
    ready:(x.status.containerStatuses||[]).map(c=>c.ready),
    restarts:(x.status.containerStatuses||[]).map(c=>c.restartCount),
    imageIDs:(x.status.containerStatuses||[]).map(c=>c.imageID),
    conditions:(x.status.conditions||[]).filter(c=>["Ready","ContainersReady"].includes(c.type)).map(c=>({type:c.type,status:c.status,reason:c.reason,lastTransitionTime:c.lastTransitionTime}))
  }))));
} catch(e) { text(pods.output); }
const lines=logs.output.split("\n").filter(Boolean);
const recovery=lines.filter(l=>/recovered|Fanned lifecycle event|consumer started|durable unreachable|configuration rejected|consume loop closed|consumer deleted/i.test(l));
text(recovery.slice(-40).join("\n"));

