const goal = await tools.get_goal({});
const pods = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout get pods -l app=meta-fanout -o json",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:30000,
  max_output_tokens:14000,
  sandbox_permissions:"require_escalated",
  justification:"May I resolve and validate the exact AP South meta-fanout pods immediately before recycling them?"
});
text(JSON.stringify(goal));
try {
  const p=JSON.parse(pods.output);
  text(JSON.stringify((p.items||[]).map(x=>({
    name:x.metadata.name,uid:x.metadata.uid,created:x.metadata.creationTimestamp,
    deletionTimestamp:x.metadata.deletionTimestamp||null,
    ready:(x.status.containerStatuses||[]).every(c=>c.ready),
    restarts:(x.status.containerStatuses||[]).reduce((n,c)=>n+c.restartCount,0),
    imageIDs:(x.status.containerStatuses||[]).map(c=>c.imageID)
  }))));
} catch(e) { text(pods.output); }

