const logs = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout logs meta-fanout-9d5d55797-cch9h --since=5m --tail=500",
  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:30000,
  max_output_tokens:16000,
  sandbox_permissions:"require_escalated",
  justification:"May I verify the first AP South replacement created the durable and is actively consuming before recycling the second original pod?"
});
const lines=logs.output.split("\n").filter(Boolean);
text(lines.filter(l=>/Lifecycle consumer started|Fanned lifecycle event|durable unreachable|consumer deleted|consume loop closed|configuration rejected|no responders|no heartbeat/i.test(l)).slice(-100).join("\n"));

