const logs1 = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout logs meta-fanout-9d5d55797-cch9h --since=5m --tail=500",
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:18000,
  sandbox_permissions:"require_escalated",justification:"May I verify the first AP South replacement remains healthy and processing the retained backlog?"
});
const logs2 = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout logs meta-fanout-9d5d55797-ljtdw --since=5m --tail=500",
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:18000,
  sandbox_permissions:"require_escalated",justification:"May I verify the second AP South replacement attached to the lifecycle durable and is consuming?"
});
function summarize(out){
 const lines=out.split("\n").filter(Boolean);
 const bad=lines.filter(l=>/durable unreachable|consumer deleted|consume loop closed|configuration rejected|no responders|no heartbeat|Lifecycle fan failed|panic/i.test(l));
 const started=lines.filter(l=>/Lifecycle consumer started/i.test(l));
 const fanned=lines.filter(l=>/Fanned lifecycle event/i.test(l));
 return {started:started.slice(-2),fannedCount:fanned.length,latestFanned:fanned.slice(-3),badCount:bad.length,latestBad:bad.slice(-8)};
}
text(JSON.stringify({pod:"cch9h",...summarize(logs1.output)}));
text(JSON.stringify({pod:"ljtdw",...summarize(logs2.output)}));

