const files = await tools.exec_command({
  cmd:"rg -n -C 5 'consumer info|nats consumer|natsctl|resource_lifecycle' apps/natsctl mise-tasks docs 2>/dev/null | head -240",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:10000,
  max_output_tokens:16000
});
text(files.output);

const r = await tools.exec_command({
  cmd:"./mise-tasks/ops/natsctl --context eks-prod-ap-south-1 -- consumer info resource_lifecycle_v1 meta-fanout-lifecycle --json",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:30000,
  max_output_tokens:16000,
  sandbox_permissions:"require_escalated",
  justification:"May I launch the audited read-only natsctl job in AP South to verify the recreated lifecycle durable's stored configuration and backlog?"
});
text(r.output);
if (r.session_id) text(JSON.stringify({session_id:r.session_id}));

const r = await tools.exec_command({
  cmd:"./mise-tasks/ops/natsctl --context eks-prod-ap-south-1-admin -- consumer info resource_lifecycle_v1 meta-fanout-lifecycle --json",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:30000,
  max_output_tokens:18000,
  sandbox_permissions:"require_escalated",
  justification:"May I use the AP South admin context to run the audited read-only natsctl consumer-info job and clean it up afterward?"
});
text(r.output);
if (r.session_id) text(JSON.stringify({session_id:r.session_id}));

const p = await tools.update_plan({explanation:"AP South was recovered by sequentially recycling both stale pods. Both replacements are Ready and consuming; the recreated durable has the intended stored config and its retained backlog is fully drained.",plan:[
  {step:"Track the merged commit through image build and deploy workflow",status:"completed"},
  {step:"Confirm Fleet promotes the new meta-fanout image",status:"completed"},
  {step:"Verify the deployment and pod health in all seven cells",status:"completed"},
  {step:"Observe lifecycle-consumer health signals through the initial rollout window",status:"in_progress"},
  {step:"Report rollout completion or actionable failures",status:"pending"}
]});
text(JSON.stringify(p));

const s = await tools.exec_command({cmd:"sleep 30",workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:1000});
const dep = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout get deployment meta-fanout -o json",
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:12000,
  sandbox_permissions:"require_escalated",justification:"May I continue monitoring AP South deployment health through the recovery window?"
});
const logs = await tools.exec_command({
  cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout logs -l app=meta-fanout --all-containers=true --prefix=true --since=3m --tail=1000",
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:20000,
  sandbox_permissions:"require_escalated",justification:"May I scan AP South replacement logs for recurrence during the recovery window?"
});
try {
 const d=JSON.parse(dep.output);
 text(JSON.stringify({replicas:d.status?.replicas||0,updated:d.status?.updatedReplicas||0,ready:d.status?.readyReplicas||0,available:d.status?.availableReplicas||0,unavailable:d.status?.unavailableReplicas||0,conditions:d.status?.conditions}));
} catch(e){text(dep.output)}
const bad=logs.output.split("\n").filter(l=>/durable unreachable|consumer deleted|consume loop closed|configuration rejected|no responders|no heartbeat|Lifecycle fan failed|panic/i.test(l));
text(JSON.stringify({badCount:bad.length,latest:bad.slice(-10)}));

