const s=await tools.exec_command({cmd:"sleep 30",workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:1000});
const r=await tools.exec_command({
 cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout get deployment meta-fanout -o 'jsonpath={.status.updatedReplicas}{\"/\"}{.status.readyReplicas}{\"/\"}{.status.availableReplicas}{\"/\"}{.status.replicas}{\"\\n\"}'",
 workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:2000,
 sandbox_permissions:"require_escalated",justification:"May I continue the AP South post-recovery availability watch?"
});
text(r.output);

const s=await tools.exec_command({cmd:"sleep 30",workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:1000});
const d=await tools.exec_command({cmd:"date -u '+%Y-%m-%dT%H:%M:%SZ'",workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:10000,max_output_tokens:1000});
text(d.output);

const contexts=["eks-staging-us-west-2","eks-staging-eu-west-1","eks-staging-us-east-2","eks-prod-us-east-2","eks-prod-eu-central-1","eks-prod-ap-southeast-2","eks-prod-ap-south-1"];
const calls=[];
for(const ctx of contexts) calls.push(tools.exec_command({
 cmd:`kubectl --context ${ctx} -n meta-fanout get deployment meta-fanout -o json`,
 workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:12000,
 sandbox_permissions:"require_escalated",justification:`May I perform the final meta-fanout deployment verification in ${ctx}?`
}));
calls.push(tools.exec_command({
 cmd:"kubectl --context eks-prod-ap-south-1 -n meta-fanout logs -l app=meta-fanout --all-containers=true --prefix=true --since=6m --tail=2000",
 workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:24000,
 sandbox_permissions:"require_escalated",justification:"May I perform the final AP South error scan after the five-minute recovery window?"
}));
const rs=await Promise.all(calls);
for(let i=0;i<contexts.length;i++){
 try{const d=JSON.parse(rs[i].output);text(JSON.stringify({
  context:contexts[i],tag:d.metadata?.annotations?.["fleet.entire.io/source-tag"],
  image:d.spec?.template?.spec?.containers?.[0]?.image,
  generation:`${d.metadata?.generation}/${d.status?.observedGeneration}`,
  replicas:d.status?.replicas||0,updated:d.status?.updatedReplicas||0,
  ready:d.status?.readyReplicas||0,available:d.status?.availableReplicas||0,unavailable:d.status?.unavailableReplicas||0
 }))}catch(e){text(JSON.stringify({context:contexts[i],error:rs[i].output}))}
}
const lines=rs[contexts.length].output.split("\n").filter(Boolean);
const bad=lines.filter(l=>/durable unreachable|consumer deleted|consume loop closed|configuration rejected|no responders|no heartbeat|Lifecycle fan failed|panic/i.test(l));
const fanned=lines.filter(l=>/Fanned lifecycle event/i.test(l));
text(JSON.stringify({apSouthWindow:{badCount:bad.length,latestBad:bad.slice(-10),fannedCount:fanned.length,latestFanned:fanned.slice(-3)}}));

