payload.input:
const r = await tools.exec_command({
  cmd:"./mise-tasks/ops/natsctl --context eks-prod-ap-south-1-admin -- consumer info resource_lifecycle_v1 meta-fanout-lifecycle --json",
  workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",
  yield_time_ms:30000,
  max_output_tokens:18000,
  sandbox_permissions:"require_escalated",
  justification:"May I run the final audited read-only AP South consumer-info check and clean up its one-off job?"
});
text(r.output);
if (r.session_id) text(JSON.stringify({session_id:r.session_id}));

const p = await tools.update_plan({explanation:"All seven cells are on the intended image and fully available. AP South remained clean through the five-minute recovery window; its durable is correctly configured, actively consumed through sequence 14,573, and has no pending or redelivered messages.",plan:[
  {step:"Track the merged commit through image build and deploy workflow",status:"completed"},
  {step:"Confirm Fleet promotes the new meta-fanout image",status:"completed"},
  {step:"Verify the deployment and pod health in all seven cells",status:"completed"},
  {step:"Observe lifecycle-consumer health signals through the initial rollout window",status:"completed"},
  {step:"Report rollout completion or actionable failures",status:"completed"}
]});
let g;
try { g = await tools.update_goal({status:"complete"}); } catch(e) { g = {error:String(e)}; }
text(JSON.stringify(p)); text(JSON.stringify(g));

const contexts=["eks-staging-us-west-2","eks-staging-eu-west-1","eks-staging-us-east-2","eks-prod-us-east-2","eks-prod-eu-central-1","eks-prod-ap-southeast-2","eks-prod-ap-south-1"];
const calls=[];
for(const ctx of contexts){
 calls.push(tools.exec_command({
  cmd:`kubectl --context ${ctx} -n meta-fanout get deployment meta-fanout -o json`,
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:12000,
  sandbox_permissions:"require_escalated",justification:`May I verify current meta-fanout deployment health in ${ctx}?`
 }));
 calls.push(tools.exec_command({
  cmd:`kubectl --context ${ctx} -n meta-fanout get pods -l app=meta-fanout -o json`,
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:14000,
  sandbox_permissions:"require_escalated",justification:`May I verify current meta-fanout pod readiness and restart counts in ${ctx}?`
 }));
 calls.push(tools.exec_command({
  cmd:`kubectl --context ${ctx} -n meta-fanout logs -l app=meta-fanout --all-containers=true --prefix=true --since=10m --tail=2000`,
  workdir:"/Users/nodo/work/tasks/nats-robustness",yield_time_ms:30000,max_output_tokens:24000,
  sandbox_permissions:"require_escalated",justification:`May I scan the last ten minutes of meta-fanout logs in ${ctx} for flow failures?`
 }));
}
const rs=await Promise.all(calls);
for(let i=0;i<contexts.length;i++){
 let dep={},pods={};
 try{const d=JSON.parse(rs[i*3].output);dep={
  tag:d.metadata?.annotations?.["fleet.entire.io/source-tag"],
  image:d.spec?.template?.spec?.containers?.[0]?.image,
  generation:`${d.metadata?.generation}/${d.status?.observedGeneration}`,
  desired:d.spec?.replicas||0,updated:d.status?.updatedReplicas||0,ready:d.status?.readyReplicas||0,available:d.status?.availableReplicas||0,unavailable:d.status?.unavailableReplicas||0
 }}catch(e){dep={error:String(e)}}
 try{const p=JSON.parse(rs[i*3+1].output);pods={
  count:p.items?.length||0,ready:(p.items||[]).filter(x=>(x.status?.containerStatuses||[]).every(c=>c.ready)).length,
  restarts:(p.items||[]).reduce((n,x)=>n+(x.status?.containerStatuses||[]).reduce((m,c)=>m+c.restartCount,0),0)
 }}catch(e){pods={error:String(e)}}
 const lines=rs[i*3+2].output.split("\n").filter(Boolean);
 const bad=lines.filter(l=>/durable unreachable|consumer deleted|consume loop closed|configuration rejected|no responders|no heartbeat|Lifecycle fan failed|panic/i.test(l));
 const fanned=lines.filter(l=>/Fanned lifecycle event/i.test(l));
 text(JSON.stringify({context:contexts[i],deployment:dep,pods,badCount:bad.length,latestBad:bad.slice(-3),fannedCount:fanned.length,latestFanned:fanned.slice(-2)}));
}

