const rs=await Promise.all(contexts.map(ctx=>tools.exec_command({
 cmd:`./mise-tasks/ops/natsctl --context ${ctx}-admin -- consumer info resource_lifecycle_v1 meta-fanout-lifecycle --json`,
 workdir:"/Users/nodo/work/tasks/nats-robustness/fleet",yield_time_ms:30000,max_output_tokens:18000,
 sandbox_permissions:"require_escalated",justification:`May I run the audited read-only natsctl consumer-info check in ${ctx} and automatically clean up its one-off job?`
})));
for(let i=0;i<contexts.length;i++){
 const out=rs[i].output;
 const a=out.indexOf("{"),b=out.lastIndexOf("}");
 if(a<0||b<a){text(JSON.stringify({context:contexts[i],error:out.slice(-1500)}));continue}
 try{
  const x=JSON.parse(out.slice(a,b+1));
  text(JSON.stringify({context:contexts[i],created:x.created,
   consumerSeq:x.delivered?.consumer_seq,streamSeq:x.delivered?.stream_seq,
   ackConsumerSeq:x.ack_floor?.consumer_seq,ackStreamSeq:x.ack_floor?.stream_seq,
   pending:x.num_pending,ackPending:x.num_ack_pending,redelivered:x.num_redelivered,waiting:x.num_waiting,
   maxDeliver:x.config?.max_deliver,maxAckPending:x.config?.max_ack_pending,backoff:x.config?.backoff
  }));
 }catch(e){text(JSON.stringify({context:contexts[i],parseError:String(e),tail:out.slice(-1500)}))}
}

