  workdir:"/Users/nodo/work/tasks/nats-robustness",
  yield_time_ms:10000,
  max_output_tokens:12000
});
const hits=ALL_TOOLS.filter(x=>/linear|entire.*trail/i.test(x.name+" "+x.description));
text(mem.output);
text(JSON.stringify(hits));

