  // Initiative name, ID, identifier (e.g., INIT-123), or slug. If provided, updates the existing initiative
  id?: string;
  // Label names or IDs as a JSON array of strings (e.g. ["Bug", "Urgent"]). Replaces the full label set; existing labels not included are removed. Omit to leave labels unchanged
  labels?: Array<string>;
  // Lead team name, key, or ID. Null to remove the lead team
