+	if err != nil {
+		t.Fatalf("legacy JetStream context: %v", err)
+	}
+	legacySub, err := legacyJS.PullSubscribe(
+		"events.repo", "stale_owner_durable", nats.ManualAck(),
+	)
+	if err != nil {
+		t.Fatalf("legacy PullSubscribe: %v", err)
+	}
+
+	url := controlNC.ConnectedUrl()
+	runnerNCs := make([]*nats.Conn, 2)
+	done := make(chan error, len(runnerNCs))
+	got := make(chan string, 8)
+	cfg := Config{
+		Stream: "events_v1", Durable: "stale_owner_durable",
+		FilterSubject: "events.repo", Name: "testconsumer", SpanName: "test.consume",
+	}
+	for i := range runnerNCs {
+		runnerNCs[i], err = nats.Connect(url)
+		if err != nil {
+			t.Fatalf("connect runner %d: %v", i, err)
+		}
+		t.Cleanup(runnerNCs[i].Close)
+		go func(nc *nats.Conn) {
+			done <- Run(ctx, nc, cfg, func(m jetstream.Msg) {
+				if err := m.Ack(); err != nil {
