+// TestRunRecreatesAfterStaleLegacyOwnerDeletesReplacement reproduces the
+// mixed-version rollout race from COR-1252. The legacy PullSubscribe API marks
+// a durable it creates as library-owned and deletes it when that subscription
+// drains. If new Run replicas recreate the shared durable before the old
+// subscription finishes draining, that stale owner can delete the replacement.
+// nats.go may then leave the replacement ConsumeContexts open while reporting
+// pull errors, so watching only ConsumeContext.Closed leaves every replica
+// alive but permanently deaf.
+func TestRunRecreatesAfterStaleLegacyOwnerDeletesReplacement(t *testing.T) {
+	compressRunRetries(t)
+	controlNC, js := runTestEnv(t)
+	ctx, cancel := context.WithCancel(context.Background())
+	defer cancel()
+	if _, err := js.CreateStream(ctx, jetstream.StreamConfig{
+		Name: "events_v1", Subjects: []string{"events.>"},
+	}); err != nil {
+		t.Fatalf("create stream: %v", err)
+	}
+
+	legacyJS, err := controlNC.JetStream()
+	if err != nil {
+		t.Fatalf("legacy JetStream context: %v", err)
+	}
+	legacySub, err := legacyJS.PullSubscribe(
+		"events.repo", "stale_owner_durable", nats.ManualAck(),
+	)
+	if err != nil {
+		t.Fatalf("legacy PullSubscribe: %v", err)
+	}
+
+	url := controlNC.ConnectedUrl()
+	runnerNCs := make([]*nats.Conn, 2)
+	done := make(chan error, len(runnerNCs))
+	got := make(chan string, 8)
+	cfg := Config{
+		Stream: "events_v1", Durable: "stale_owner_durable",
+		FilterSubject: "events.repo", Name: "testconsumer", SpanName: "test.consume",
+	}
+	for i := range runnerNCs {
+		runnerNCs[i], err = nats.Connect(url)
+		if err != nil {
+			t.Fatalf("connect runner %d: %v", i, err)
+		}
+		t.Cleanup(runnerNCs[i].Close)
+		go func(nc *nats.Conn) {
+			done <- Run(ctx, nc, cfg, func(m jetstream.Msg) {
+				if err := m.Ack(); err != nil {
+					t.Errorf("ack: %v", err)
+				}
+				got <- string(m.Data())
+			})
+		}(runnerNCs[i])
+	}
+
+	waitForWaiters := func(want int) {
+		t.Helper()
+		deadline := time.Now().Add(5 * time.Second)
+		for {
+			cons, lookupErr := js.Consumer(ctx, cfg.Stream, cfg.Durable)
+			if lookupErr == nil {
+				info, infoErr := cons.Info(ctx)
+				if infoErr == nil && info.NumWaiting == want {
+					return
+				}
+			}
+			if time.Now().After(deadline) {
+				t.Fatalf("durable never reached %d waiting replicas", want)
+			}
+			time.Sleep(10 * time.Millisecond)
+		}
+	}
+
+	// Both new replicas have bound to the legacy-created durable. The first
+	// deletion closes their initial consume loops, which Run already knows how
+	// to recreate.
+	waitForWaiters(2)
+	if err := js.DeleteConsumer(ctx, cfg.Stream, cfg.Durable); err != nil {
+		t.Fatalf("delete original durable: %v", err)
+	}
+	waitForWaiters(2)
+
+	// The old subscription still believes it owns the durable. Its drain now
+	// deletes the replacement while both new ConsumeContexts are live.
+	if err := legacySub.Drain(); err != nil {
+		t.Fatalf("drain stale legacy subscription: %v", err)
+	}
+	waitForWaiters(2)
+
+	if _, err := js.Publish(ctx, "events.repo", []byte("after-stale-drain")); err != nil {
+		t.Fatalf("publish after stale drain: %v", err)
+	}
+	deadline := time.After(5 * time.Second)
+	for {
+		select {
+		case payload := <-got:
+			if payload == "after-stale-drain" {
+				cancel()
+				for range runnerNCs {
+					if err := <-done; err != nil {
+						t.Fatalf("Run returned %v on cancel, want nil", err)
+					}
+				}
+				return
+			}
+		case <-deadline:
+			t.Fatal("message did not arrive after the stale legacy owner deleted the replacement durable")
+		}
+	}
+}
+
+// TestRunRecreatesWhenReconnectFindsDurableDeleted pins the terminal state
+// that the mixed-version rollout exposed: a ConsumeContext can remain open
+// after reconnecting to a broker where its durable no longer exists. Its pull
+// loop reports ErrNoResponders, but Closed never fires, so Run must use the
+// asynchronous error as a prompt to verify the durable and recreate it.
+func TestRunRecreatesWhenReconnectFindsDurableDeleted(t *testing.T) {
+	compressRunRetries(t)
+	storeDir := t.TempDir()
+	var servers []*natsserver.Server
+	startServer := func(port int) *natsserver.Server {
+		t.Helper()
+		s, err := natsserver.NewServer(&natsserver.Options{
+			Host: "127.0.0.1", Port: port, NoLog: true, NoSigs: true,
+			JetStream: true, StoreDir: storeDir,
+		})
+		if err != nil {
+			t.Fatalf("new embedded nats server: %v", err)
+		}
+		go s.Start()
+		if !s.ReadyForConnections(10 * time.Second) {
+			s.Shutdown()
+			t.Fatal("embedded nats server not ready in time")
+		}
+		servers = append(servers, s)
+		return s
+	}
+	t.Cleanup(func() {
+		for _, s := range servers {
+			s.Shutdown()
+		}
+	})
+
+	firstServer := startServer(-1)
+	port := firstServer.Addr().(*net.TCPAddr).Port
+	url := firstServer.ClientURL()
+	adminNC, err := nats.Connect(url)
+	if err != nil {
+		t.Fatalf("connect admin: %v", err)
+	}
+	js, err := jetstream.New(adminNC)
+	if err != nil {
+		t.Fatalf("admin jetstream.New: %v", err)
+	}
+	if _, err := js.CreateStream(t.Context(), jetstream.StreamConfig{
+		Name: "events_v1", Subjects: []string{"events.>"},
+	}); err != nil {
+		t.Fatalf("create stream: %v", err)
+	}
+
+	runnerNC, err := nats.Connect(url,
+		nats.MaxReconnects(-1),
+		nats.CustomReconnectDelay(func(int) time.Duration { return 500 * time.Millisecond }),
+	)
+	if err != nil {
+		t.Fatalf("connect runner: %v", err)
+	}
+	t.Cleanup(runnerNC.Close)
+	ctx, cancel := context.WithCancel(context.Background())
+	defer cancel()
+	done := make(chan error, 1)
+	got := make(chan string, 1)
+	cfg := Config{
+		Stream: "events_v1", Durable: "reconnect_durable",
+		FilterSubject: "events.repo", Name: "testconsumer", SpanName: "test.consume",
+	}
+	go func() {
+		done <- Run(ctx, runnerNC, cfg, func(m jetstream.Msg) {
+			if err := m.Ack(); err != nil {
+				t.Errorf("ack: %v", err)
+			}
+			got <- string(m.Data())
+		})
+	}()
+
+	waitForConsumer := func(js jetstream.JetStream) {
+		t.Helper()
+		deadline := time.Now().Add(5 * time.Second)
+		for {
+			cons, lookupErr := js.Consumer(t.Context(), cfg.Stream, cfg.Durable)
+			if lookupErr == nil {
+				if info, infoErr := cons.Info(t.Context()); infoErr == nil && info.NumWaiting == 1 {
+					return
+				}
+			}
+			if time.Now().After(deadline) {
+				t.Fatal("durable never appeared with a waiting runner")
+			}
+			time.Sleep(10 * time.Millisecond)
+		}
+	}
+	waitForConsumer(js)
+
+	// Keep the runner disconnected long enough to delete the durable before
+	// its consume loop can restore a pull request on the restarted broker.
+	adminNC.Close()
+	firstServer.Shutdown()
+	deadline := time.Now().Add(5 * time.Second)
+	for runnerNC.Status() != nats.RECONNECTING {
+		if time.Now().After(deadline) {
+			t.Fatal("runner connection never entered reconnecting state")
+		}
+		time.Sleep(10 * time.Millisecond)
+	}
+	secondServer := startServer(port)
+	adminNC, err = nats.Connect(secondServer.ClientURL())
+	if err != nil {
+		t.Fatalf("connect replacement admin: %v", err)
+	}
+	defer adminNC.Close()
+	js, err = jetstream.New(adminNC)
+	if err != nil {
+		t.Fatalf("replacement admin jetstream.New: %v", err)
+	}
+	if err := js.DeleteConsumer(t.Context(), cfg.Stream, cfg.Durable); err != nil {
+		t.Fatalf("delete durable before runner reconnect: %v", err)
+	}
+
+	waitForConsumer(js)
+	if _, err := js.Publish(t.Context(), "events.repo", []byte("after-reconnect")); err != nil {
+		t.Fatalf("publish after reconnect: %v", err)
+	}
+	select {
+	case payload := <-got:
+		if payload != "after-reconnect" {
+			t.Fatalf("payload = %q, want after-reconnect", payload)
+		}
+	case <-time.After(5 * time.Second):
+		t.Fatal("message did not arrive after reconnecting without the durable")
+	}
+
+	cancel()
+	select {
+	case err := <-done:
+		if err != nil {
+			t.Fatalf("Run returned %v on cancel, want nil", err)
+		}
+	case <-time.After(10 * time.Second):
+		t.Fatal("Run did not return after ctx cancel")
+	}
+}
