+	if !ok {
+		t.Fatalf("embedded server address has type %T, want *net.TCPAddr", firstServer.Addr())
+	}
+	port := tcpAddr.Port
+	url := firstServer.ClientURL()
+	adminNC, err := nats.Connect(url)
